window.MRX=window.MRX.concat([{"id": "s-èin", "name": "Je distingue [è] et [in]", "sub": "lait ou lin ?", "cls": "gn", "badge": "è/in", "steps": [{"t": "teach", "title": "[è] ou [in] ?", "say": "Dans lait, on entend è. Dans lin, on entend in. Lait, lin. Paix, pain. Mère, mine. Écoute la voyelle au milieu du mot : est-elle orale, comme è, ou nasale, comme in ?", "html": "<p class=\"big\">Dans <span class=\"w v\">lait</span>, on entend [è]. Dans <span class=\"w v\">lin</span>, on entend [in].</p><div class=\"row\"><span class=\"w v\">lait / lin</span><span class=\"w v\">paix / pain</span><span class=\"w v\">mère / mine</span></div><p>Écoute la voyelle au milieu du mot : orale comme [è], ou nasale comme [in] ?</p>", "chk": {"q": "Dans « pain », j'entends…", "o": ["[è]", "[in]"], "a": 1}}, {"t": "sort", "q": "Classe les mots dans les paniers.", "cats": [{"k": "c0", "label": "[è]", "cls": "g"}, {"k": "c1", "label": "[in]", "cls": "v"}], "items": [{"w": "lait", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "reine", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "tête", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "neige", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "pain", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "lapin", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "matin", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "main", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Quel mot a le son [in] ?", "opts": ["lait", "lin"], "ans": 1, "ok": "Oui : lin.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Quel mot a le son [in] ?", "opts": ["paix", "pain"], "ans": 1, "ok": "Oui : pain.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Quel mot a le son [in] ?", "opts": ["mère", "mine"], "ans": 1, "ok": "Oui : mine.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : du l___t", "opts": ["ai", "ei", "in", "ain"], "ans": 0, "ok": "Oui : du lait.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un lap___", "opts": ["ai", "ei", "in", "ain"], "ans": 2, "ok": "Oui : un lapin.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : la r___ne", "opts": ["ai", "ei", "in", "ain"], "ans": 1, "ok": "Oui : la reine.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une m___", "opts": ["ai", "ei", "in", "ain"], "ans": 3, "ok": "Oui : une main.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "tapmany", "q": "Touche les mots où tu entends [in].", "tokens": ["Le", "lapin", "mange", "du", "pain", "près", "de", "la", "reine."], "ans": [1, 4], "ok": "Oui : lapin, pain."}, {"t": "tapmany", "q": "Touche les mots où tu entends [è].", "tokens": ["Le", "lapin", "mange", "du", "pain", "près", "de", "la", "reine."], "ans": [5, 8], "ok": "Oui : près, reine."}]}, {"id": "s-uou", "name": "Je distingue [u] et [ou]", "sub": "rue ou roue ?", "cls": "gn", "badge": "u/ou", "steps": [{"t": "teach", "title": "[u] ou [ou] ?", "say": "Dans rue, on entend u. Dans roue, on entend ou. Rue, roue. Pull, poule. Pour faire u, les lèvres sont très serrées. Pour faire ou, elles sont plus arrondies.", "html": "<p class=\"big\">Dans <span class=\"w v\">rue</span>, on entend [u]. Dans <span class=\"w v\">roue</span>, on entend [ou].</p><div class=\"row\"><span class=\"w v\">rue / roue</span><span class=\"w v\">pull / poule</span></div><p>Pour [u], les lèvres sont très serrées. Pour [ou], elles sont plus arrondies.</p>", "chk": {"q": "Dans « roue », j'entends…", "o": ["[u]", "[ou]"], "a": 1}}, {"t": "sort", "q": "Classe les mots dans les paniers.", "cats": [{"k": "c0", "label": "[u]", "cls": "g"}, {"k": "c1", "label": "[ou]", "cls": "v"}], "items": [{"w": "lune", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "pull", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "plume", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "tortue", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "roue", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "poule", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "rouge", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "mouton", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "On le met sur soi quand il fait froid.", "opts": ["pull", "poule"], "ans": 0, "ok": "Oui : le pull.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Elle pond des œufs.", "opts": ["poule", "pull"], "ans": 0, "ok": "Oui : la poule.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Elle tourne autour de son axe.", "opts": ["roue", "rue"], "ans": 0, "ok": "Oui : la roue.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "On y marche dans une ville.", "opts": ["rue", "roue"], "ans": 0, "ok": "Oui : la rue.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une l___ne", "opts": ["u", "ou"], "ans": 0, "ok": "Oui : une lune.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une r___e de vélo", "opts": ["u", "ou"], "ans": 1, "ok": "Oui : une roue de vélo.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une p___le", "opts": ["u", "ou"], "ans": 1, "ok": "Oui : une poule.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une tort___e", "opts": ["u", "ou"], "ans": 0, "ok": "Oui : une tortue.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : du r___ge", "opts": ["u", "ou"], "ans": 1, "ok": "Oui : du rouge.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "tapmany", "q": "Touche le mot où tu entends [ou].", "tokens": ["La", "poule", "suit", "la", "tortue", "dans", "la", "rue."], "ans": [1], "ok": "Oui : poule."}, {"t": "tapmany", "q": "Touche les mots où tu entends [u].", "tokens": ["La", "poule", "suit", "la", "tortue", "dans", "la", "rue."], "ans": [4, 7], "ok": "Oui : tortue, rue."}]}, {"id": "s-éè", "name": "Je distingue [é] et [è]", "sub": "bébé ou père ?", "cls": "gn", "badge": "é/è", "steps": [{"t": "teach", "title": "[é] ou [è] ?", "say": "Ces deux sons se ressemblent, mais ils ne sont pas identiques. É dans bébé, vélo. È dans père, fête. Écoute la voyelle et observe les lettres qui l'écrivent.", "html": "<p class=\"big\">Ces deux sons se ressemblent, mais ils ne sont pas identiques.</p><p>[é] dans <div class=\"row\"><span class=\"w v\">bébé</span><span class=\"w v\">vélo</span></div></p><p>[è] dans <div class=\"row\"><span class=\"w v\">père</span><span class=\"w v\">fête</span></div></p><p>Écoute la voyelle et observe les lettres qui l'écrivent.</p>", "chk": {"q": "Dans « père », j'entends…", "o": ["[é]", "[è]"], "a": 1}}, {"t": "sort", "q": "Classe les mots dans les paniers.", "cats": [{"k": "c0", "label": "[é]", "cls": "g"}, {"k": "c1", "label": "[è]", "cls": "v"}], "items": [{"w": "bébé", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "été", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "nez", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "vélo", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "père", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "fête", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "reine", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "tête", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : un b___bé", "opts": ["é", "è", "ê", "ei"], "ans": 0, "ok": "Oui : un bébé.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une f___te", "opts": ["é", "è", "ê", "ei"], "ans": 2, "ok": "Oui : une fête.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : le p___re", "opts": ["é", "è", "ê", "ei"], "ans": 1, "ok": "Oui : le père.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : l'___té", "opts": ["é", "è", "ê", "ei"], "ans": 0, "ok": "Oui : l'été.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une r___ne", "opts": ["é", "è", "ê", "ei"], "ans": 3, "ok": "Oui : une reine.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "match", "q": "Relie les mots qui ont le même son final.", "pairs": [{"l": "bébé", "r": "été"}, {"l": "nez", "r": "clé"}, {"l": "fête", "r": "tête"}, {"l": "père", "r": "mère"}]}, {"t": "tapmany", "q": "Touche les mots où tu entends [é].", "tokens": ["Le", "bébé", "fête", "son", "premier", "été", "chez", "son", "père."], "ans": [1, 4, 5, 6], "ok": "Oui : bébé, premier, été, chez."}, {"t": "tapmany", "q": "Touche les mots où tu entends [è].", "tokens": ["Le", "bébé", "fête", "son", "premier", "été", "chez", "son", "père."], "ans": [2, 8], "ok": "Oui : fête, père."}]}, {"id": "s-ail", "name": "Soleil, feuille, grenouille", "sub": "ail, eil, euil, ouil, ille", "cls": "gn", "badge": "eil", "steps": [{"t": "teach", "title": "Des sons qui finissent par [j]", "say": "Certains sons se terminent par un petit son, comme dans fille. Ils peuvent s'écrire de plusieurs façons. Ail : travail, portail. Eil : soleil, réveil. Euil : feuille, fauteuil. Ouil : grenouille, nouille. Ille : fille, bille.", "html": "<p class=\"big\">Certains sons se terminent par un petit son [j], comme dans fille.</p><p>ail : <div class=\"row\"><span class=\"w v\">travail</span><span class=\"w v\">portail</span></div></p><p>eil : <div class=\"row\"><span class=\"w v\">soleil</span><span class=\"w v\">réveil</span></div></p><p>euil : <div class=\"row\"><span class=\"w v\">feuille</span><span class=\"w v\">fauteuil</span></div></p><p>ouil : <div class=\"row\"><span class=\"w v\">grenouille</span><span class=\"w v\">nouille</span></div></p><p>ille : <div class=\"row\"><span class=\"w v\">fille</span><span class=\"w v\">bille</span></div></p>", "chk": {"q": "Dans « soleil », je vois…", "o": ["ail", "eil", "ouil"], "a": 1}}, {"t": "sort", "q": "Classe chaque mot selon son écriture.", "cats": [{"k": "c0", "label": "ail", "cls": "g"}, {"k": "c1", "label": "eil", "cls": "v"}, {"k": "c2", "label": "euil", "cls": "p"}, {"k": "c3", "label": "ouil", "cls": "g"}, {"k": "c4", "label": "ille", "cls": "g"}], "items": [{"w": "portail", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "soleil", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "réveil", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "feuille", "cat": "c2", "hint": "Écoute bien le mot."}, {"w": "grenouille", "cat": "c3", "hint": "Écoute bien le mot."}, {"w": "fille", "cat": "c4", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : le sol___", "opts": ["ail", "eil", "euil", "ouil", "ille"], "ans": 1, "ok": "Oui : le soleil.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une f___le", "opts": ["ail", "eil", "euil", "ouil", "ille"], "ans": 2, "ok": "Oui : une feuille.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une gren___le", "opts": ["ail", "eil", "euil", "ouil", "ille"], "ans": 3, "ok": "Oui : une grenouille.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une f___", "opts": ["ail", "eil", "euil", "ouil", "ille"], "ans": 4, "ok": "Oui : une fille.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un port___", "opts": ["ail", "eil", "euil", "ouil", "ille"], "ans": 0, "ok": "Oui : un portail.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "match", "q": "Relie l'indice au mot.", "pairs": [{"l": "Il éclaire le jour", "r": "soleil"}, {"l": "Elle pousse sur un arbre", "r": "feuille"}, {"l": "Elle coasse près de l'eau", "r": "grenouille"}, {"l": "C'est une enfant", "r": "fille"}]}, {"t": "tapmany", "q": "Touche les mots qui ont ces sons.", "tokens": ["La", "fille", "voit", "une", "grenouille", "près", "du", "portail."], "ans": [1, 4, 7], "ok": "Oui : fille, grenouille, portail."}]}, {"id": "s-ui", "name": "Je découvre le son ui", "sub": "fruit, huit, nuit", "cls": "gn", "badge": "ui", "steps": [{"t": "teach", "title": "Le son ui", "say": "Dans fruit, on entend le son ui. Fruit, huit, nuit, cuisine. Il ne faut pas le confondre avec ou dans roue, ni avec oi dans poire.", "html": "<p class=\"big\">Dans <span class=\"w v\">fruit</span>, on entend le son écrit <b>ui</b>.</p><div class=\"row\"><span class=\"w v\">fruit</span><span class=\"w v\">huit</span><span class=\"w v\">nuit</span><span class=\"w v\">cuisine</span></div><p>Il ne faut pas le confondre avec ou dans roue, ni avec oi dans poire.</p>", "chk": {"q": "Dans « nuit », je vois…", "o": ["ou", "oi", "ui"], "a": 2}}, {"t": "sort", "q": "Classe les mots dans les paniers.", "cats": [{"k": "c0", "label": "UI", "cls": "g"}, {"k": "c1", "label": "OU", "cls": "v"}, {"k": "c2", "label": "OI", "cls": "p"}], "items": [{"w": "nuit", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "huit", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "roue", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "poule", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "poire", "cat": "c2", "hint": "Écoute bien le mot."}, {"w": "voiture", "cat": "c2", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : la n___t", "opts": ["ui", "ou", "oi"], "ans": 0, "ok": "Oui : la nuit.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une p___le", "opts": ["ui", "ou", "oi"], "ans": 1, "ok": "Oui : une poule.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une p___re", "opts": ["ui", "ou", "oi"], "ans": 2, "ok": "Oui : une poire.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un fr___t", "opts": ["ui", "ou", "oi"], "ans": 0, "ok": "Oui : un fruit.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une v___ture", "opts": ["ui", "ou", "oi"], "ans": 2, "ok": "Oui : une voiture.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "On le mange.", "opts": ["fruit", "frouit"], "ans": 0, "ok": "Oui : un fruit.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Il vient après sept.", "opts": ["huit", "hout"], "ans": 0, "ok": "Oui : huit.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "On y prépare les repas.", "opts": ["cuisine", "couisine"], "ans": 0, "ok": "Oui : la cuisine.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "tapmany", "q": "Touche les mots qui contiennent ui.", "tokens": ["La", "nuit,", "Lila", "prépare", "huit", "fruits", "dans", "la", "cuisine."], "ans": [1, 4, 5, 8], "ok": "Oui : nuit, huit, fruits, cuisine."}]}, {"id": "s-emuet", "name": "Le e final muet", "sub": "table, robe, lune", "cls": "gn", "badge": "e", "steps": [{"t": "teach", "title": "Le e muet", "say": "À la fin de nombreux mots, la lettre e ne s'entend pas : on l'appelle le e muet. Une table, une robe, une lune, une porte. On voit le e à l'écrit, mais on ne le prononce pas comme une syllabe supplémentaire.", "html": "<p class=\"big\">À la fin de nombreux mots, la lettre <b>e</b> ne s'entend pas : c'est le <b>e muet</b>.</p><div class=\"row\"><span class=\"w v\">une table</span><span class=\"w v\">une robe</span><span class=\"w v\">une lune</span><span class=\"w v\">une porte</span></div><p>On voit le e à l'écrit, mais on ne le prononce pas comme une syllabe en plus.</p>", "chk": {"q": "Dans « table », le e de la fin…", "o": ["s'entend", "ne s'entend pas"], "a": 1}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "e final muet", "cls": "g"}, {"k": "c1", "label": "Pas de e final", "cls": "v"}], "items": [{"w": "table", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "robe", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "lune", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "porte", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "robot", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "vélo", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : une tabl___", "opts": ["e", "é"], "ans": 0, "ok": "Oui : une table.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une rob___", "opts": ["e", "é"], "ans": 0, "ok": "Oui : une robe.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : la lun___", "opts": ["e", "é"], "ans": 0, "ok": "Oui : la lune.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une port___", "opts": ["e", "é"], "ans": 0, "ok": "Oui : une porte.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "La … brille dans le ciel.", "opts": ["table", "robe", "lune", "porte"], "ans": 2, "ok": "Oui : la lune.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Le livre est posé sur la …", "opts": ["table", "robe", "lune", "porte"], "ans": 0, "ok": "Oui : la table.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Elle met une jolie …", "opts": ["table", "robe", "lune", "porte"], "ans": 1, "ok": "Oui : robe.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Il ferme la …", "opts": ["table", "robe", "lune", "porte"], "ans": 3, "ok": "Oui : la porte.", "ko": "Écoute le mot et regarde bien les lettres."}]}]);

