window.MRX=window.MRX.concat([{"id": "s-un", "name": "J'entends un / um", "sub": "brun, lundi, parfum", "cls": "gn", "badge": "un", "steps": [{"t": "teach", "title": "Le son [un]", "say": "Dans brun, lundi et parfum, on entend le son nasal un. Il peut s'écrire u n ou u m.", "html": "<p class=\"big\">Dans <span class=\"w v\">brun</span>, <span class=\"w v\">lundi</span> et <span class=\"w v\">parfum</span>, on entend le son nasal [un].</p><p>Il peut s'écrire <b>un</b> ou <b>um</b>.</p>", "chk": {"q": "Dans « parfum », le son s'écrit…", "o": ["un", "um"], "a": 1}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "J'entends [un]", "cls": "g"}, {"k": "c1", "label": "Je ne l'entends pas", "cls": "v"}], "items": [{"w": "brun", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "parfum", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "lundi", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "chacun", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "lapin", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "voiture", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : br___", "opts": ["un", "um"], "ans": 0, "ok": "Oui : brun.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : parf___", "opts": ["un", "um"], "ans": 1, "ok": "Oui : parfum.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : l___di", "opts": ["un", "um"], "ans": 0, "ok": "Oui : lundi.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : chac___", "opts": ["un", "um"], "ans": 0, "ok": "Oui : chacun.", "ko": "Écoute le mot et regarde bien les lettres."}]}, {"id": "s-oin", "name": "J'entends oin", "sub": "coin, loin, point", "cls": "gn", "badge": "oin", "steps": [{"t": "teach", "title": "Le son oin", "say": "Dans coin, loin et point, les lettres o, i, n produisent le son oin.", "html": "<p class=\"big\">Dans <span class=\"w v\">coin</span>, <span class=\"w v\">loin</span> et <span class=\"w v\">point</span>, les lettres <b>oin</b> produisent un seul son.</p>", "chk": {"q": "Dans « loin », je vois…", "o": ["oi", "oin", "on"], "a": 1}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "Il y a oin", "cls": "g"}, {"k": "c1", "label": "Pas de oin", "cls": "v"}], "items": [{"w": "coin", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "loin", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "point", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "soin", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "poisson", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "maison", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : un c___", "opts": ["oin", "oi", "on"], "ans": 0, "ok": "Oui : un coin.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : très l___", "opts": ["oin", "oi", "on"], "ans": 0, "ok": "Oui : très loin.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un p___t", "opts": ["oin", "oi", "on"], "ans": 0, "ok": "Oui : un point.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : prendre s___ de son chat", "opts": ["oin", "oi", "on"], "ans": 0, "ok": "Oui : prendre soin de son chat.", "ko": "Écoute le mot et regarde bien les lettres."}]}, {"id": "s-ien", "name": "J'entends ien", "sub": "chien, bien", "cls": "gn", "badge": "ien", "steps": [{"t": "teach", "title": "Le son ien", "say": "Dans chien et bien, les lettres i, e, n se prononcent ien.", "html": "<p class=\"big\">Dans <span class=\"w v\">chien</span> et <span class=\"w v\">bien</span>, les lettres <b>ien</b> se lisent ensemble.</p>", "chk": {"q": "Dans « chien », je vois…", "o": ["ion", "ien", "in"], "a": 1}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "Avec ien", "cls": "g"}, {"k": "c1", "label": "Sans ien", "cls": "v"}], "items": [{"w": "chien", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "bien", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "lien", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "rien", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "lion", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "matin", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : le ch___", "opts": ["ien", "ion", "in"], "ans": 0, "ok": "Oui : le chien.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : tout va b___", "opts": ["ien", "ion", "in"], "ans": 0, "ok": "Oui : tout va bien.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un l___ entre deux objets", "opts": ["ien", "ion", "in"], "ans": 0, "ok": "Oui : un lien entre deux objets.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : il ne reste plus r___", "opts": ["ien", "ion", "in"], "ans": 0, "ok": "Oui : il ne reste plus rien.", "ko": "Écoute le mot et regarde bien les lettres."}]}, {"id": "s-ion", "name": "J'entends ion / tion", "sub": "camion, récréation", "cls": "gn", "badge": "ion", "steps": [{"t": "teach", "title": "ion et tion", "say": "Dans camion, on entend ion à la fin. Dans beaucoup de mots, t, i, o, n se prononce comme sion. Camion, attention, récréation.", "html": "<p class=\"big\">Dans <span class=\"w v\">camion</span>, on entend <b>ion</b> à la fin.</p><p class=\"big\">Dans beaucoup de mots, <b>tion</b> se prononce comme « sion ».</p><div class=\"row\"><span class=\"w v\">attention</span><span class=\"w v\">récréation</span></div>", "chk": {"q": "« tion » se prononce souvent comme…", "o": ["« tion »", "« sion »"], "a": 1}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "ion", "cls": "g"}, {"k": "c1", "label": "tion", "cls": "v"}], "items": [{"w": "camion", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "lion", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "avion", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "attention", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "récréation", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "addition", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : un cam___", "opts": ["ion", "tion"], "ans": 0, "ok": "Oui : un camion.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : atten___", "opts": ["ion", "tion"], "ans": 1, "ok": "Oui : attention.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un av___", "opts": ["ion", "tion"], "ans": 0, "ok": "Oui : un avion.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : la récréa___", "opts": ["ion", "tion"], "ans": 1, "ok": "Oui : la récréation.", "ko": "Écoute le mot et regarde bien les lettres."}]}, {"id": "s-y", "name": "Les deux façons de lire y", "sub": "stylo, crayon", "cls": "gn", "badge": "y", "steps": [{"t": "teach", "title": "La lettre y", "say": "Le y de stylo se prononce comme i. Dans crayon et noyau, il permet d'entendre un son de liaison, comme dans fille, entre les voyelles.", "html": "<p class=\"big\">Le y de <span class=\"w v\">stylo</span> se prononce comme <b>i</b>.</p><p class=\"big\">Dans <span class=\"w v\">crayon</span> et <span class=\"w v\">noyau</span>, il fait un son de liaison entre les voyelles, comme dans fille.</p>", "chk": {"q": "Dans « stylo », le y se lit comme…", "o": ["i", "é"], "a": 0}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "y se lit comme i", "cls": "g"}, {"k": "c1", "label": "y fait une liaison", "cls": "v"}], "items": [{"w": "stylo", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "pyjama", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "crayon", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "noyau", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "voyage", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : un cra___on", "opts": ["y", "i"], "ans": 0, "ok": "Oui : un crayon.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un no___au", "opts": ["y", "i"], "ans": 0, "ok": "Oui : un noyau.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un st___lo", "opts": ["y", "i"], "ans": 0, "ok": "Oui : un stylo.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un vo___age", "opts": ["y", "i"], "ans": 0, "ok": "Oui : un voyage.", "ko": "Écoute le mot et regarde bien les lettres."}]}, {"id": "s-h", "name": "Le h muet", "sub": "hibou, homme", "cls": "gn", "badge": "h", "steps": [{"t": "teach", "title": "La lettre h", "say": "Au début de hibou et homme, la lettre h ne se prononce pas. Elle est écrite, mais elle ne fait pas de son. Attention : c h et p h sont des groupes de lettres différents. Ch dans chat fait le son ch. Ph dans photo fait le son f.", "html": "<p class=\"big\">Au début de <span class=\"w v\">hibou</span> et <span class=\"w v\">homme</span>, le <b>h</b> ne se prononce pas.</p><p>Attention : ch et ph sont différents.</p><p>h dans hibou : aucun son<br>ch dans chat : son [ch]<br>ph dans photo : son [f]</p>", "chk": {"q": "Dans « hibou », le h…", "o": ["fait un son", "ne fait pas de son"], "a": 1}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "h muet", "cls": "g"}, {"k": "c1", "label": "ch", "cls": "v"}, {"k": "c2", "label": "ph", "cls": "p"}], "items": [{"w": "homme", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "hibou", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "histoire", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "chat", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "cheval", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "photo", "cat": "c2", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : un ___ibou", "opts": ["h", "ch", "ph"], "ans": 0, "ok": "Oui : un hibou.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une ___oto", "opts": ["h", "ch", "ph"], "ans": 2, "ok": "Oui : une photo.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : un ___eval", "opts": ["h", "ch", "ph"], "ans": 1, "ok": "Oui : un cheval.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une ___istoire", "opts": ["h", "ch", "ph"], "ans": 0, "ok": "Oui : une histoire.", "ko": "Écoute le mot et regarde bien les lettres."}]}, {"id": "s-w", "name": "La lettre w", "sub": "wagon, kiwi", "cls": "gn", "badge": "w", "steps": [{"t": "teach", "title": "La lettre w", "say": "La lettre w peut se prononcer de différentes façons selon le mot : comme v dans wagon, et comme ou dans kiwi.", "html": "<p class=\"big\">La lettre <b>w</b> se prononce de différentes façons selon le mot.</p><p>comme [v] dans <span class=\"w v\">wagon</span></p><p>proche de « ou » dans <span class=\"w v\">kiwi</span></p>", "chk": {"q": "Dans « wagon », le w se lit comme…", "o": ["[v]", "« ou »"], "a": 0}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "w comme [v]", "cls": "g"}, {"k": "c1", "label": "w proche de « ou »", "cls": "v"}], "items": [{"w": "wagon", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "kiwi", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "water-polo", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "Il y a un w", "cls": "g"}, {"k": "c1", "label": "Pas de w", "cls": "v"}], "items": [{"w": "wagon", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "kiwi", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "water-polo", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "vélo", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "voiture", "cat": "c1", "hint": "Écoute bien le mot."}]}]}, {"id": "s-eille", "name": "eille ou aille ?", "sub": "abeille, paille", "cls": "gn", "badge": "eil", "steps": [{"t": "teach", "title": "eille et aille", "say": "Ces écritures se ressemblent, mais le début du son n'est pas le même. Eille dans abeille. Aille dans paille, taille.", "html": "<p class=\"big\">Ces écritures se ressemblent, mais le début du son n'est pas le même.</p><p><b>eille</b> dans <div class=\"row\"><span class=\"w v\">abeille</span><span class=\"w v\">oreille</span></div></p><p><b>aille</b> dans <div class=\"row\"><span class=\"w v\">paille</span><span class=\"w v\">taille</span></div></p>", "chk": {"q": "Dans « paille », je vois…", "o": ["eille", "aille"], "a": 1}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "eille", "cls": "g"}, {"k": "c1", "label": "aille", "cls": "v"}], "items": [{"w": "abeille", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "bouteille", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "oreille", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "paille", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "taille", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "bataille", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : une ab___", "opts": ["eille", "aille"], "ans": 0, "ok": "Oui : une abeille.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : de la p___", "opts": ["eille", "aille"], "ans": 1, "ok": "Oui : de la paille.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une bout___", "opts": ["eille", "aille"], "ans": 0, "ok": "Oui : une bouteille.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une bat___", "opts": ["eille", "aille"], "ans": 1, "ok": "Oui : une bataille.", "ko": "Écoute le mot et regarde bien les lettres."}]}, {"id": "s-èe", "name": "Le e qui fait [è]", "sub": "belle, terre, veste", "cls": "gn", "badge": "ell", "steps": [{"t": "teach", "title": "e devant deux consonnes", "say": "Dans plusieurs mots, la lettre e se prononce è quand elle est suivie de deux consonnes. Belle, terre, chouette, veste. Il n'y a pas forcément d'accent sur le e : ce sont les lettres qui suivent qui aident à lire le son.", "html": "<p class=\"big\">La lettre <b>e</b> se prononce [è] quand elle est suivie de deux consonnes.</p><div class=\"row\"><span class=\"w v\">belle</span><span class=\"w v\">terre</span><span class=\"w v\">chouette</span><span class=\"w v\">veste</span></div><p>Pas d'accent sur le e : ce sont les lettres qui suivent qui aident à lire le son.</p>", "chk": {"q": "Dans « belle », le e se lit…", "o": ["[è]", "[é]"], "a": 0}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "e sans accent qui fait [è]", "cls": "g"}, {"k": "c1", "label": "Autres", "cls": "v"}], "items": [{"w": "belle", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "terre", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "veste", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "chouette", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "vélo", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "bébé", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "Complète : une b___lle", "opts": ["e", "é", "è"], "ans": 0, "ok": "Oui : une belle.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : la t___rre", "opts": ["e", "é", "è"], "ans": 0, "ok": "Oui : la terre.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une v___ste", "opts": ["e", "é", "è"], "ans": 0, "ok": "Oui : une veste.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : une chou___tte", "opts": ["e", "é", "è"], "ans": 0, "ok": "Oui : une chouette.", "ko": "Écoute le mot et regarde bien les lettres."}]}, {"id": "s-e2", "name": "Le petit e de « le »", "sub": "le, petit, cheval", "cls": "gn", "badge": "e", "steps": [{"t": "teach", "title": "Le e faible", "say": "Dans le, petit et cheval, le e se prononce souvent comme un petit son faible. Ce son est différent de é dans bébé et de è dans mère.", "html": "<p class=\"big\">Dans <span class=\"w v\">le</span>, <span class=\"w v\">petit</span> et <span class=\"w v\">cheval</span>, le e fait un petit son faible.</p><p>Ce son est différent de é dans bébé et de è dans mère.</p>", "chk": {"q": "Dans « petit », le e se lit…", "o": ["comme é", "comme è", "comme un petit e faible"], "a": 2}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "Petit e faible", "cls": "g"}, {"k": "c1", "label": "Autre son", "cls": "v"}], "items": [{"w": "le", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "cheval", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "petit", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "bébé", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "mère", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "sort", "q": "Classe les mots dans les paniers.", "cats": [{"k": "c0", "label": "e faible", "cls": "g"}, {"k": "c1", "label": "é", "cls": "v"}, {"k": "c2", "label": "è", "cls": "p"}], "items": [{"w": "cheval", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "petit", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "le", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "bébé", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "vélo", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "fête", "cat": "c2", "hint": "Écoute bien le mot."}]}]}, {"id": "s-muet", "name": "Les lettres muettes à la fin", "sub": "chat, lit, gros, grand", "cls": "gn", "badge": "t", "steps": [{"t": "teach", "title": "La lettre muette", "say": "Dans beaucoup de mots, la dernière consonne ne s'entend pas : chat, lit, gros, grand. Mais il existe aussi des mots où la consonne finale s'entend. On vérifie donc le mot au lieu de deviner.", "html": "<p class=\"big\">Dans beaucoup de mots, la dernière consonne <b>ne s'entend pas</b>.</p><div class=\"row\"><span class=\"w v\">chat</span><span class=\"w v\">lit</span><span class=\"w v\">gros</span><span class=\"w v\">grand</span></div><p>Mais dans certains mots, elle s'entend. On vérifie le mot au lieu de deviner.</p>", "chk": {"q": "Dans « chat », le t de la fin…", "o": ["s'entend", "ne s'entend pas"], "a": 1}}, {"t": "sort", "q": "Classe les mots.", "cats": [{"k": "c0", "label": "Consonne finale muette", "cls": "g"}, {"k": "c1", "label": "Consonne finale entendue", "cls": "v"}], "items": [{"w": "chat", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "lit", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "gros", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "grand", "cat": "c0", "hint": "Écoute bien le mot."}, {"w": "avec", "cat": "c1", "hint": "Écoute bien le mot."}, {"w": "neuf", "cat": "c1", "hint": "Écoute bien le mot."}]}, {"t": "choice", "q": "petit → petite : quelle lettre s'entend maintenant ?", "opts": ["t", "e", "p"], "ans": 0, "ok": "Oui : t.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "grand → grande : quelle lettre s'entend maintenant ?", "opts": ["n", "d", "g"], "ans": 1, "ok": "Oui : d.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "gros → grosse : quelle lettre s'entend maintenant ?", "opts": ["s", "o", "r"], "ans": 0, "ok": "Oui : s.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "chat → chatte : quelle lettre s'entend maintenant ?", "opts": ["c", "h", "t"], "ans": 2, "ok": "Oui : t.", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : Le chat dort dans son li___.", "opts": ["t", "d", "s"], "ans": 0, "ok": "Oui : Le chat dort dans son lit..", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : Le ballon est gro___.", "opts": ["t", "d", "s"], "ans": 2, "ok": "Oui : Le ballon est gros..", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : Le sac est gran___.", "opts": ["t", "d", "s"], "ans": 1, "ok": "Oui : Le sac est grand..", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "choice", "q": "Complète : Le pull est peti___.", "opts": ["t", "d", "s"], "ans": 0, "ok": "Oui : Le pull est petit..", "ko": "Écoute le mot et regarde bien les lettres."}, {"t": "tapmany", "q": "Touche les mots qui finissent par une lettre muette.", "tokens": ["Le", "grand", "chat", "dort", "dans", "le", "petit", "lit."], "ans": [1, 2, 3, 4, 6, 7], "ok": "Oui : grand, chat, dort, dans, petit, lit."}]}]);

/* Mots longs : syllabes qui s'allument */
(function(){try{var st=document.createElement('style');st.textContent='.syl{display:flex;flex-direction:column;align-items:center;gap:8px;margin:14px 0;padding:12px;border-radius:16px;background:var(--gn-bg)}.syl .sw{display:flex;flex-wrap:wrap;justify-content:center;font:800 2rem/1.1 var(--display)}.syl .sw span{padding:2px 3px;border-radius:8px;transition:background .25s,color .25s,transform .25s}.syl .sw span.on{background:var(--sun);color:#3b2b00;transform:translateY(-4px) scale(1.12)}.syl .sw span.hard{text-decoration:underline 3px var(--verb);text-underline-offset:5px}.syl .sw span.sep::after{content:"–";color:var(--soft);margin:0 2px}.syl.full .sw span.sep::after{content:""}.syl.full .sw span{background:var(--pro-bg)}.syl .sb{display:flex;gap:8px}.syl button{padding:8px 14px;border-radius:12px;font-weight:800;background:var(--gn);color:#fff}.syl button.g2{background:var(--card);color:var(--ink);border:2px solid var(--line)}';document.head.appendChild(st);}catch(e){}})();
window.mrSyl=function(){
  var sp=function(t){try{say(t)}catch(e){}};
  document.querySelectorAll('.syl').forEach(function(b){
    var s=b.dataset.s.split('|'),m=b.dataset.m;
    b.innerHTML='<div class="sw">'+s.map(function(x,i){return '<span class="'+(i<s.length-1?'sep ':'')+(m!==undefined&&+m===i?'hard':'')+'">'+x+'</span>'}).join('')+'</div><div class="sb"><button class="cut">✂ Découper</button><button class="g2 hear">🔊 Le mot</button></div>';
    var ss=b.querySelectorAll('.sw span'),busy=0,w=function(ms){return new Promise(function(r){setTimeout(r,ms)})};
    b.querySelector('.hear').onclick=function(){sp(b.dataset.w)};
    if(m!==undefined)ss[+m].onclick=function(){sp(s[+m]);};
    b.querySelector('.cut').onclick=async function(){if(busy)return;busy=1;b.classList.remove('full');
      for(var i=0;i<ss.length;i++){ss[i].classList.add('on');sp(s[i]);await w(900);ss[i].classList.remove('on');}
      await w(250);for(var i=0;i<ss.length;i++){ss[i].classList.add('on');await w(260);ss[i].classList.remove('on');}
      b.classList.add('full');sp(b.dataset.w);busy=0;};
  });
};

