window.MRX=window.MRX.concat([{"id": "ml-2", "name": "Leçon 1 — L'expédition des mots géants", "sub": "Lire les mots longs", "cls": "gn", "badge": "📖", "steps": [{"t": "teach", "title": "L'expédition des mots géants", "say": "Mission : aider l'exploratrice Zoé à lire les mots cachés dans son carnet. Zoé appuie sur le bouton Découper. Les syllabes s'allument une à une, puis tu relis le mot entier.", "html": "<p class=\"big\">Mission : aider l'exploratrice Zoé à lire les mots cachés dans son carnet.</p><p>Appuie sur « Découper » : les syllabes s'allument une à une, puis tu relis le mot entier.</p><div class=\"syl\" data-s=\"mé|di|ca|ment\" data-w=\"médicament\"></div>", "js": "syl", "chk": {"q": "Après les syllabes, je…", "o": ["relis le mot entier", "m'arrête"], "a": 0}}, {"t": "teach", "title": "Je découvre : parasol", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"pa|ra|sol\" data-w=\"parasol\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : avalanche", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"a|va|lanche\" data-w=\"avalanche\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : écrivain", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"é|cri|vain\" data-w=\"écrivain\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : vocabulaire", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"vo|ca|bu|laire\" data-w=\"vocabulaire\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : enveloppe", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"en|ve|loppe\" data-w=\"enveloppe\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : invitation", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"in|vi|ta|tion\" data-w=\"invitation\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : calculatrice", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"cal|cu|la|trice\" data-w=\"calculatrice\"></div>", "js": "syl"}, {"t": "choice", "q": "Combien de syllabes dans « parasol » ?", "opts": ["2", "3", "4"], "ans": 1, "ok": "Oui : pa-ra-sol, 3 syllabes.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "Combien de syllabes dans « vocabulaire » ?", "opts": ["2", "3", "4"], "ans": 2, "ok": "Oui : vo-ca-bu-laire, 4 syllabes.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "Combien de syllabes dans « enveloppe » ?", "opts": ["2", "3", "4"], "ans": 1, "ok": "Oui : en-ve-loppe, 3 syllabes.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "Combien de syllabes dans « calculatrice » ?", "opts": ["2", "3", "4"], "ans": 2, "ok": "Oui : cal-cu-la-trice, 4 syllabes.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "build", "q": "Remets les syllabes dans l'ordre.", "words": ["sol", "pa", "ra"], "ans": "pa-ra-sol", "j": "-", "ok": "Bravo : pa-ra-sol → parasol", "ko": "Lis les morceaux un par un. Recommence."}, {"t": "build", "q": "Remets les syllabes dans l'ordre.", "words": ["vain", "é", "cri"], "ans": "é-cri-vain", "j": "-", "ok": "Bravo : é-cri-vain → écrivain", "ko": "Lis les morceaux un par un. Recommence."}, {"t": "build", "q": "Remets les syllabes dans l'ordre.", "words": ["tion", "in", "ta", "vi"], "ans": "in-vi-ta-tion", "j": "-", "ok": "Bravo : in-vi-ta-tion → invitation", "ko": "Lis les morceaux un par un. Recommence."}, {"t": "build", "q": "Remets les syllabes dans l'ordre.", "words": ["laire", "vo", "bu", "ca"], "ans": "vo-ca-bu-laire", "j": "-", "ok": "Bravo : vo-ca-bu-laire → vocabulaire", "ko": "Lis les morceaux un par un. Recommence."}, {"t": "choice", "q": "cal – cu – la – trice, c'est…", "opts": ["calculatrice", "caravane", "chocolat"], "ans": 0, "ok": "Oui : calculatrice.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "en – ve – loppe, c'est…", "opts": ["enveloppe", "avalanche", "écrivain"], "ans": 0, "ok": "Oui : enveloppe.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "a – va – lanche, c'est…", "opts": ["aventure", "avalanche", "invitation"], "ans": 1, "ok": "Oui : avalanche.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "teach", "title": "Je garde les groupes de lettres ensemble", "say": "Certains morceaux contiennent plusieurs lettres qui travaillent ensemble. On les garde ensemble pendant la lecture. Vain dans écrivain. Tion dans invitation. Trice dans calculatrice.", "html": "<p class=\"big\">Certains morceaux contiennent plusieurs lettres qui travaillent ensemble. On les garde ensemble pendant la lecture.</p><div class=\"syl\" data-s=\"é|cri|vain\" data-w=\"écrivain\" data-m=\"2\"></div><div class=\"syl\" data-s=\"in|vi|ta|tion\" data-w=\"invitation\" data-m=\"3\"></div><div class=\"syl\" data-s=\"cal|cu|la|trice\" data-w=\"calculatrice\" data-m=\"3\"></div>", "js": "syl", "chk": {"q": "Dans « invitation », je garde ensemble…", "o": ["t-i-o-n", "tion"], "a": 1}}, {"t": "teach", "title": "Le carnet de Zoé", "say": "Zoé ouvre une enveloppe. Elle y trouve une invitation pour partir en avalanche ? Non : une invitation à découvrir le vocabulaire caché dans la montagne !", "html": "<p class=\"big\">Zoé ouvre une enveloppe.<br>Elle y trouve une invitation pour partir en avalanche ?<br>Non : une invitation à découvrir le vocabulaire caché dans la montagne !</p><div class=\"syl\" data-s=\"en|ve|loppe\" data-w=\"enveloppe\"></div><div class=\"syl\" data-s=\"in|vi|ta|tion\" data-w=\"invitation\"></div><div class=\"syl\" data-s=\"vo|ca|bu|laire\" data-w=\"vocabulaire\"></div>", "js": "syl"}, {"t": "choice", "q": "Qu'est-ce que Zoé trouve dans l'enveloppe ?", "opts": ["une avalanche", "une invitation", "une montagne"], "ans": 1, "ok": "Oui : une invitation.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "teach", "title": "Le geste à retenir", "say": "J'écoute le mot. Je lis les syllabes éclairées. Je relis le mot entier.", "html": "<p class=\"big\">J'écoute le mot.<br>Je lis les syllabes éclairées.<br>Je relis le mot entier.</p>", "js": "syl", "chk": {"q": "Après les syllabes éclairées, je…", "o": ["relis le mot entier", "passe au mot suivant"], "a": 0}}]}]);

/* Dictées */
(function(){try{var st=document.createElement('style');st.textContent='.dic-in{width:100%;font:800 1.7rem/1.2 var(--display);padding:12px 14px;border-radius:14px;border:3px solid var(--line);background:var(--card);color:var(--ink);text-align:center}.dic-in:focus{outline:0;border-color:var(--gn)}.dic-ans{font:800 2rem/1.3 var(--display);text-align:center;letter-spacing:.02em}.dic-ans .bad{background:color-mix(in srgb,var(--ko) 25%,transparent);color:var(--ko);border-radius:6px;padding:0 2px}.dic-ans .ok{color:var(--ok)}.mrhl{color:var(--verb);text-decoration:underline 3px;text-underline-offset:5px}.dic-row button.go{background:var(--gn);color:#fff;border-color:var(--gn)}.dic-row{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}.dic-row button{padding:10px 16px;border-radius:14px;font-weight:800;background:var(--card);border:2px solid var(--line)}.dic-list{display:flex;flex-wrap:wrap;gap:6px}.dic-list span{padding:4px 10px;border-radius:99px;font-weight:800}';document.head.appendChild(st);}catch(e){}})();
window.mrDicLog=window.mrDicLog||{ok:[],ko:[]};
var mrVoice=function(t,r){try{speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(t);u.lang='fr-FR';u.rate=r||.9;speechSynthesis.speak(u);}catch(e){try{say(t)}catch(_){}}};
var mrSlow=async function(t){var w=t.replace(/[.!?]/g,'').split(/\s+/);for(var i=0;i<w.length;i++){mrVoice(w[i],.7);await new Promise(function(r){setTimeout(r,850)})}};
var mrNorm=function(x){return String(x||'').toLowerCase().replace(/[’`]/g,"'").replace(/\s+/g,' ').replace(/\s*([.!?,])\s*$/,'').trim()};
var mrFrag=function(w,ok){try{var k='mr-fragile',f=JSON.parse(localStorage.getItem(k)||'{}');if(ok){if(f[w])f[w]--;if(f[w]<=0)delete f[w];}else f[w]=(f[w]||0)+1;localStorage.setItem(k,JSON.stringify(f));}catch(e){}};
var mrDiff=function(a,b){var i=0;while(i<a.length&&i<b.length&&a[i]===b[i])i++;var j=0;while(j<a.length-i&&j<b.length-i&&a[a.length-1-j]===b[b.length-1-j])j++;var mid=a.slice(i,a.length-j);return esc(a.slice(0,i))+(mid?'<span class="bad">'+esc(mid)+'</span>':'<span class="bad">_</span>')+esc(a.slice(a.length-j))};
var mrPhr=function(typed,good){var t=mrNorm(typed).split(' '),g=mrNorm(good).split(' ');return g.map(function(w,i){var x=t[i]||'';return x===w?'<span class="ok">'+esc(x)+'</span>':'<span class="bad">'+esc(x||'_')+'</span>'}).join(' ')+(t.length>g.length?' <span class="bad">'+esc(t.slice(g.length).join(' '))+'</span>':'')};
window.mrDic=function(s){
  var m=M[cur.m];if(cur.i===m.steps.findIndex(function(x){return x.js==='dic'})&&!st.tries&&!st.val)window.mrDicLog={ok:[],ko:[]};
  var show=function(t){if(s.ans)return esc(s.ans);return s.hard?esc(s.w).replace(esc(s.hard),'<b class="mrhl">'+esc(s.hard)+'</b>'):esc(s.w)};
  var lead=s.lead?esc(s.lead):s.mode==='s'?'Mini-dictée':'Dictée',q=s.q?esc(s.q):s.show?'Écoute le mot. Il est mal écrit : corrige-le.':s.mode==='p'?'Écoute, puis touche la bonne écriture.':s.mode==='s'?'Écoute la phrase, puis écris-la.':'Écoute le mot, puis écris-le.';
  var done=st.ok||st.tries>=2,body='';
  if(s.mode==='p'){body='<div style="display:flex;flex-direction:column;gap:10px">'+s.opts.map(function(o,k){var c=(done&&o===(s.ans||s.w))?'good':(st.pick===k&&o!==(s.ans||s.w)?'bad':'');return '<button class="opt '+c+'" data-dp="'+k+'" '+(done?'disabled':'')+'>'+esc(o)+'</button>'}).join('')+'</div>';}
  else{body=(s.show&&!done?'<p class="dic-ans" style="text-decoration:line-through;text-decoration-color:var(--ko);opacity:.75">'+esc(s.show)+'</p>':'')+(st.tries&&!st.ok?'<p class="dic-ans">'+(s.mode==='s'?mrPhr(st.val,s.w):mrDiff(mrNorm(st.val),mrNorm(s.w)))+'</p>':'')+(done?'':'<input id="dicin" class="dic-in" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" value="'+esc(st.val||s.show||'')+'" placeholder="J\'écris ici"><div class="dic-row"><button class="go" id="dicok">Valider</button></div>');}
  var fb='';
  if(st.ok)fb=fbBox('ok',s.ans?'Oui, bravo !':'Bravo ! Tu as bien écouté et choisi les bonnes lettres.')+'<p class="dic-ans">'+show()+'</p>';
  else if(st.tries>=2)fb=fbBox('ko','Voici la bonne écriture. Ce mot reviendra pour une révision.')+'<p class="dic-ans">'+show()+'</p>';
  else if(st.tries===1)fb=fbBox('ko',s.mode==='p'?'Pas tout à fait. Réécoute et essaie encore.':'Regarde la partie en couleur, réécoute et essaie encore.');
  app.innerHTML=head()+'<div class="card"><span class="lead">'+lead+'</span><h2>'+q+'</h2><div class="dic-row"><button id="dicsay">🔊 Écouter</button>'+(s.mode==='s'?'<button id="dicslow">🐢 Lentement</button>':'')+'</div>'+body+fb+(done?nextBtn():'')+'</div>';
  document.getElementById('dicsay').onclick=function(){mrVoice(s.w)};
  var sl=document.getElementById('dicslow');if(sl)sl.onclick=function(){mrSlow(s.w)};
  var fin=function(ok){var L=window.mrDicLog,k=s.mode==='s'?s.w:s.w;if(ok){if(L.ok.indexOf(k)<0)L.ok.push(k)}else if(L.ko.indexOf(k)<0)L.ko.push(k);mrFrag(k,ok);if(s.tag)mrFragSet(s.tag,ok)};
  var check=function(v,k){st.val=v;st.pick=k;var good=s.mode==='p'?s.opts[k]===(s.ans||s.w):mrNorm(v)===mrNorm(s.w);
    if(good){st.ok=1;fin(!st.tries)}else{st.tries=(st.tries||0)+1;if(st.tries>=2)fin(false);else setTimeout(function(){mrVoice(s.w)},300)}step();};
  document.querySelectorAll('[data-dp]').forEach(function(b){b.onclick=function(){check('',+b.dataset.dp)}});
  var ok=document.getElementById('dicok'),inp=document.getElementById('dicin');
  if(ok)ok.onclick=function(){if(mrNorm(inp.value))check(inp.value)};
  if(inp)inp.onkeydown=function(e){if(e.key==='Enter'&&ok)ok.click()};
  if(!st.tries&&!st.ok&&!st.played){st.played=1;setTimeout(function(){mrVoice(s.w)},350)}
};
window.mrDicEnd=function(s){var L=window.mrDicLog||{ok:[],ko:[]};
  app.innerHTML=head()+'<div class="card"><span class="lead">Bravo</span><h2>Tu as transformé des sons en mots écrits !</h2>'+
  (L.ok.length?'<p><b>Réussis du premier coup :</b></p><div class="dic-list">'+L.ok.map(function(w){return '<span style="background:var(--pro-bg)">'+esc(w)+'</span>'}).join('')+'</div>':'')+
  (L.ko.length?'<p><b>À réécouter :</b></p><div class="dic-list">'+L.ko.map(function(w){return '<span style="background:color-mix(in srgb,var(--ko) 18%,var(--card))">'+esc(w)+'</span>'}).join('')+'</div><p>Ces mots reviendront dans une courte dictée de révision.</p>':'')+nextBtn()+'</div>';
  try{mrVoice('Tu as transformé des sons en mots écrits !')}catch(e){}};

window.MRX=window.MRX.concat([{"id": "dic-1", "name": "Dictée 1 — De l'oreille au crayon", "sub": "J'écoute, je repère, j'écris", "cls": "gn", "badge": "✏️", "steps": [{"t": "teach", "title": "De l'oreille au crayon", "say": "Un mot entendu ne s'écrit pas toujours comme on l'imagine. Pour l'écrire, j'écoute le mot jusqu'au bout. Je le redis doucement. Je repère les syllabes et les sons. Je choisis les lettres qui correspondent. Je vérifie mon écriture. Exemple : chapeau. J'entends deux syllabes : cha, peau. Dans cha, j'entends ch puis a. Dans peau, le son o s'écrit e a u. J'écris : chapeau.", "html": "<p class=\"big\">Un mot entendu ne s'écrit pas toujours comme on l'imagine.</p><p>1. J'écoute le mot jusqu'au bout.<br>2. Je le redis doucement.<br>3. Je repère les syllabes et les sons.<br>4. Je choisis les lettres qui correspondent.<br>5. Je vérifie mon écriture.</p><p><b>Exemple : chapeau</b><br>J'entends deux syllabes : cha – peau.<br>Dans cha, j'entends ch puis a.<br>Dans peau, le son o s'écrit <b>eau</b>.<br>J'écris : chapeau.</p>", "chk": {"q": "Avant d'écrire un mot, je…", "o": ["l'écoute jusqu'au bout", "écris vite"], "a": 0}}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "chapeau", "hard": "eau", "say": "chapeau", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "jardin", "hard": "in", "say": "jardin", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "lapin", "hard": "in", "say": "lapin", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "girafe", "hard": "g", "say": "girafe", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "bateau", "hard": "eau", "say": "bateau", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "chemin", "hard": "ch", "say": "chemin", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "fenêtre", "hard": "ê", "say": "fenêtre", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "maison", "hard": "ai", "say": "maison", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "branche", "hard": "an", "say": "branche", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "w", "w": "magique", "hard": "qu", "say": "magique", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "p", "w": "chapeau", "opts": ["chapo", "chapeau", "chapot"], "hard": "eau", "say": "chapeau", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "p", "w": "jardin", "opts": ["jarden", "jardin", "jardain"], "hard": "in", "say": "jardin", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "p", "w": "lapin", "opts": ["lapin", "lapain", "lapim"], "hard": "in", "say": "lapin", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "p", "w": "bateau", "opts": ["bato", "bateau", "batteau"], "hard": "eau", "say": "bateau", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "p", "w": "chemin", "opts": ["chemin", "chemain", "chimin"], "hard": "ch", "say": "chemin", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "p", "w": "maison", "opts": ["méson", "maison", "maizon"], "hard": "ai", "say": "maison", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "p", "w": "branche", "opts": ["branshe", "branche", "brance"], "hard": "ch", "say": "branche", "html": ""}, {"t": "teach", "js": "dic", "title": "Dictée", "mode": "p", "w": "magique", "opts": ["magike", "magique", "majique"], "hard": "qu", "say": "magique", "html": ""}, {"t": "tap", "q": "« chapeau » : touche le morceau difficile.", "tokens": ["ch", "a", "p", "eau"], "ans": 3, "ok": "Oui : « eau ». Plusieurs lettres peuvent écrire un seul son.", "ko": "Cherche le son qui s'écrit avec des lettres spéciales."}, {"t": "tap", "q": "« jardin » : touche le morceau difficile.", "tokens": ["j", "a", "r", "d", "in"], "ans": 4, "ok": "Oui : « in ». Plusieurs lettres peuvent écrire un seul son.", "ko": "Cherche le son qui s'écrit avec des lettres spéciales."}, {"t": "tap", "q": "« bateau » : touche le morceau difficile.", "tokens": ["b", "a", "t", "eau"], "ans": 3, "ok": "Oui : « eau ». Plusieurs lettres peuvent écrire un seul son.", "ko": "Cherche le son qui s'écrit avec des lettres spéciales."}, {"t": "tap", "q": "« chemin » : touche le morceau difficile.", "tokens": ["ch", "e", "m", "in"], "ans": 0, "ok": "Oui : « ch ». Plusieurs lettres peuvent écrire un seul son.", "ko": "Cherche le son qui s'écrit avec des lettres spéciales."}, {"t": "tap", "q": "« fenêtre » : touche le morceau difficile.", "tokens": ["f", "e", "n", "ê", "t", "r", "e"], "ans": 3, "ok": "Oui : « ê ». Plusieurs lettres peuvent écrire un seul son.", "ko": "Cherche le son qui s'écrit avec des lettres spéciales."}, {"t": "tap", "q": "« maison » : touche le morceau difficile.", "tokens": ["m", "ai", "s", "on"], "ans": 1, "ok": "Oui : « ai ». Plusieurs lettres peuvent écrire un seul son.", "ko": "Cherche le son qui s'écrit avec des lettres spéciales."}, {"t": "tap", "q": "« branche » : touche le morceau difficile.", "tokens": ["b", "r", "an", "ch", "e"], "ans": 2, "ok": "Oui : « an ». Plusieurs lettres peuvent écrire un seul son.", "ko": "Cherche le son qui s'écrit avec des lettres spéciales."}, {"t": "tap", "q": "« magique » : touche le morceau difficile.", "tokens": ["m", "a", "g", "i", "qu", "e"], "ans": 4, "ok": "Oui : « qu ». Plusieurs lettres peuvent écrire un seul son.", "ko": "Cherche le son qui s'écrit avec des lettres spéciales."}, {"t": "teach", "js": "dic", "title": "Mini-dictée", "mode": "s", "w": "Le lapin court dans le jardin.", "say": "Le lapin court dans le jardin.", "html": ""}, {"t": "teach", "js": "dic", "title": "Mini-dictée", "mode": "s", "w": "Le bateau passe près de la branche.", "say": "Le bateau passe près de la branche.", "html": ""}, {"t": "teach", "js": "dic", "title": "Mini-dictée", "mode": "s", "w": "La girafe regarde la maison.", "say": "La girafe regarde la maison.", "html": ""}, {"t": "teach", "js": "dicend", "title": "Bravo", "say": "Tu as transformé des sons en mots écrits !", "html": ""}]}]);

