window.MRBANK={"eau": ["bateau", "cadeau", "chapeau", "gâteau", "oiseau", "château"], "in": ["lapin", "jardin", "moulin", "sapin", "matin", "dauphin"], "ai": ["maison", "fraise", "semaine", "raisin"], "qu": ["musique", "magique", "quatre", "requin"], "ch": ["chemin", "cheval", "chaise", "chocolat"], "an": ["branche", "maman", "orange", "dimanche"], "ê": ["fenêtre", "tête", "fête", "forêt"], "muette": ["tapis", "escargot", "petit", "souris", "chat", "gros"], "ss": ["poisson", "chaussette", "tasse", "caresse"], "gn": ["montagne", "champignon", "araignée"], "ll": ["ballon", "balle", "colle"], "au": ["chaussette", "jaune", "autruche"], "é": ["vélo", "bébé", "école"], "er": ["mercredi", "perle", "merci"], "ou": ["doucement", "mouton", "poule"], "g": ["girafe", "magique", "genou"]};
window.mrFragGet=function(){try{return JSON.parse(localStorage.getItem('mr-frag2')||'{}')}catch(e){return {}}};
window.mrFragSet=function(tag,ok){if(!tag)return;try{var f=mrFragGet();f[tag]=Math.max(0,(f[tag]||0)+(ok?-1:2));if(!f[tag])delete f[tag];localStorage.setItem('mr-frag2',JSON.stringify(f))}catch(e){}};
(function(){var R={"id": "dic-rev", "name": "Mes sons fragiles", "sub": "Une petite révision", "cls": "det", "badge": "🎯"},cache=null;
 Object.defineProperty(R,'steps',{get:function(){if(cache&&cur&&M[cur.m]===R)return cache;
   var f=mrFragGet(),tags=Object.keys(f).filter(function(t){return MRBANK[t]}).sort(function(a,b){return f[b]-f[a]}).slice(0,3),out=[];
   if(!tags.length){cache=[{t:'teach',title:'Mes sons fragiles',say:'Pas encore de sons fragiles. Fais une dictée, et les sons difficiles viendront ici.',html:'<p class="big">Pas encore de sons fragiles.</p><p>Fais une dictée : les sons difficiles viendront ici pour une petite révision.</p>'}];return cache;}
   tags.forEach(function(t){var w=MRBANK[t].slice().sort(function(){return Math.random()-.5}).slice(0,tags.length===1?6:tags.length===2?3:2);w.forEach(function(x){out.push({t:'teach',js:'dic',title:'Dictée',mode:'w',w:x,hard:t==='muette'?x.slice(-1):(x.indexOf(t)>=0?t:''),tag:t,say:x,html:''})})});
   out.push({t:'teach',js:'dicend',title:'Bravo',say:'',html:''});cache=out;return cache;},set:function(){}});
 window.MRX=window.MRX.concat([R]);})();

/* Majuscule au début des réponses en plusieurs mots (« Un point », « Une majuscule ») ; les mots seuls testés restent tels quels */
window.mrCap=function(o){o=String(o);return /\s/.test(o.trim())&&/^[a-zàâäéèêëîïôöùûüç]/.test(o)?o.charAt(0).toUpperCase()+o.slice(1):o};
(function(){var run=function(){try{M.forEach(function(m){var ss;try{ss=m.steps}catch(e){return}(ss||[]).forEach(function(s){if(s.t==='choice'&&s.opts)s.opts=s.opts.map(mrCap)})})}catch(e){}};
 if(document.readyState==='complete')setTimeout(run,0);else addEventListener('load',run);})();

/* Liaisons (oral) */
(function(){try{var st=document.createElement('style');st.textContent='.lia{display:flex;flex-wrap:wrap;justify-content:center;align-items:flex-end;gap:2px;margin:12px 0;font:800 2rem/1.2 var(--display)}.lia .lwd{padding:6px 12px;border-radius:999px;background:var(--gn-bg)}.lia .llk{display:inline-grid;place-items:center;min-width:34px;height:34px;margin:0 2px 8px;border-radius:50%;background:var(--line);color:var(--soft);font-size:1.1rem;transition:.3s}.lia .llk.on{background:var(--sun);color:#3b2b00;transform:scale(1.35)}.lia .llk.no{background:none;min-width:14px}.lia-row{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}.lia-row button{padding:10px 14px;border-radius:14px;font-weight:800;background:var(--card);border:2px solid var(--line)}.lia-row button.rec{border-color:var(--verb);color:var(--verb)}.lia-row button.rec.live{background:var(--verb);color:#fff}.lia-pk{display:flex;align-items:center;gap:8px}.lia-pk .opt{flex:1}';document.head.appendChild(st);}catch(e){}})();
var liaV=function(t,r){try{speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(t);u.lang='fr-FR';u.rate=r||.85;speechSynthesis.speak(u);return u}catch(e){try{say(t)}catch(_){}}};
var liaW=function(ms){return new Promise(function(r){setTimeout(r,ms)})};
var liaHtml=function(s){var w=s.g.split(' '),L={};if(s.multi)s.multi.forEach(function(x){L[x[0]]=x[1]});else if(s.l)L[s.at-1]=s.l;
  return '<div class="lia">'+w.map(function(x,i){return '<span class="lwd">'+esc(x)+'</span>'+(i<w.length-1?(L[i]?'<span class="llk" data-i="'+i+'">'+L[i]+'</span>':'<span class="llk no"></span>'):'')}).join('')+'</div>'};
var liaPlay=async function(s,slow){var ks=document.querySelectorAll('.lia .llk[data-i]');
  if(slow){var w=s.g.replace(/[.!?]/g,'').split(' ');for(var i=0;i<w.length;i++){liaV(w[i],.75);await liaW(800)}return}
  liaV(s.g,.8);var n=s.g.split(' ').length,d=Math.max(1500,n*420);for(var k=0;k<ks.length;k++){(function(el){var i=+el.dataset.i;setTimeout(function(){el.classList.add('on');setTimeout(function(){el.classList.remove('on')},450)},d*(i+.7)/n)})(ks[k])}};
var liaRec=null;
var liaRecUI=function(s){var b=document.getElementById('liarec'),pl=document.getElementById('liame');if(!b)return;
  if(!(navigator.mediaDevices&&window.MediaRecorder)){b.style.display='none';return}
  b.onclick=async function(){try{if(liaRec&&liaRec.state==='recording'){liaRec.stop();return}
    var str=await navigator.mediaDevices.getUserMedia({audio:true}),ch=[];liaRec=new MediaRecorder(str);
    liaRec.ondataavailable=function(e){ch.push(e.data)};liaRec.onstop=function(){str.getTracks().forEach(function(t){t.stop()});var u=URL.createObjectURL(new Blob(ch,{type:liaRec.mimeType||'audio/mp4'}));st.rec=u;b.classList.remove('live');b.textContent='🎙 Recommencer';if(pl){pl.style.display='';pl.onclick=async function(){liaPlay(s);await liaW(Math.max(1600,s.g.split(' ').length*450));try{new Audio(u).play()}catch(e){}}}};
    liaRec.start();b.classList.add('live');b.textContent='⏹ Arrêter';setTimeout(function(){if(liaRec&&liaRec.state==='recording')liaRec.stop()},6000)}catch(e){b.style.display='none'}};
  if(st.rec&&pl)pl.style.display=''};
window.mrLia=function(s){
  var done=st.ok||st.tries>=2,body='',q='',fb='',lead=s.lead||'Liaisons';
  var lis='<div class="lia-row"><button id="lianat">🔊 Écouter</button><button id="liaslo">🐢 Mot par mot</button></div>';
  if(s.mode==='son'||s.mode==='yn'){q=s.mode==='son'?'Écoute, puis touche le son que tu entends entre les mots.':'Écoute : y a-t-il une liaison ?';
    body=lis+(done?liaHtml(s):'<p class="dic-ans">'+esc(s.g)+'</p>')+'<div style="display:flex;flex-direction:column;gap:10px">'+s.opts.map(function(o,k){var c=(done&&o===s.ans)?'good':(st.pick===k&&o!==s.ans?'bad':'');return '<button class="opt '+c+'" data-lo="'+k+'" '+(done?'disabled':'')+'>'+esc(mrCap(o))+'</button>'}).join('')+'</div>';
    if(st.ok)fb=fbBox('ok',s.mode==='yn'?(s.l?'Oui ! Ici, les mots se rapprochent.':'Oui ! Ici, on ne rajoute pas de son.'):'Oui ! On entend « '+s.l+' » entre les mots.');
    else if(st.tries>=2)fb=fbBox('ko',s.mode==='yn'?(s.l?'Ici, les mots se rapprochent : écoute le son '+s.l+'.':'Ici, on ne rajoute pas de son.'):(s.l?'On entend « '+s.l+' » entre les mots. Réécoute.':'Ici, on n\'entend pas de son entre les mots.'));
    else if(st.tries)fb=fbBox('ko','Pas tout à fait. Réécoute et essaie encore.');}
  else if(s.mode==='pick'){q=s.q;body='<div style="display:flex;flex-direction:column;gap:10px">'+s.items.map(function(g,k){var c=(done&&k===s.ans)?'good':(st.pick===k&&k!==s.ans?'bad':'');return '<div class="lia-pk"><button class="ghost" data-ls="'+k+'">🔊</button><button class="opt '+c+'" data-lo="'+k+'" '+(done?'disabled':'')+'>'+esc(mrCap(g))+'</button></div>'}).join('')+'</div>';
    if(st.ok)fb=fbBox('ok','Oui ! Dans « les amis », on entend z.');else if(st.tries>=2)fb=fbBox('ko','C\'est « les amis » : on entend z.');else if(st.tries)fb=fbBox('ko','Réécoute chaque groupe.');}
  else{q='Écoute, puis répète à voix haute.';done=true;body=lis+liaHtml(s)+'<div class="lia-row"><button id="liarec" class="rec">🎙 M\'enregistrer</button><button id="liame" style="display:none">▶ Comparer</button></div>';}
  app.innerHTML=head()+'<div class="card"><span class="lead">'+lead+'</span><h2>'+q+'</h2>'+body+fb+(done?nextBtn():'')+'</div>';
  var a=document.getElementById('lianat'),b=document.getElementById('liaslo');if(a)a.onclick=function(){liaPlay(s)};if(b)b.onclick=function(){liaPlay(s,1)};
  document.querySelectorAll('[data-ls]').forEach(function(x){x.onclick=function(){liaV(s.items[+x.dataset.ls])}});
  document.querySelectorAll('[data-lo]').forEach(function(x){x.onclick=function(){var k=+x.dataset.lo;st.pick=k;var good=s.mode==='pick'?k===s.ans:s.opts[k]===s.ans;if(good)st.ok=1;else st.tries=(st.tries||0)+1;step();if(good||st.tries>=2)setTimeout(function(){if(s.mode==='pick')liaV(s.items[s.ans]);else liaPlay(s)},350)}});
  liaRecUI(s);
  if(!st.played&&s.mode!=='pick'){st.played=1;setTimeout(function(){liaPlay(s)},400)}
};

window.MRX=window.MRX.concat([{"id": "lia-1", "name": "Les liaisons", "sub": "Les mots qui se rapprochent", "cls": "pro", "badge": "🗣️", "steps": [{"t": "teach", "title": "Les mots qui se rapprochent", "say": "Parfois, le dernier son d'un mot se prononce avec le mot suivant, quand celui-ci commence par une voyelle. Les amis : on entend z. Un arbre : on entend n. Petit ours : on entend t. Les mots gardent leur place, mais les sons se suivent plus facilement. On ne met pas de liaison partout.", "html": "<p class=\"big\">Parfois, le dernier son d'un mot se prononce avec le mot suivant, quand celui-ci commence par une voyelle.</p><p>les amis → on entend <b>z</b> : lé-za-mi<br>un arbre → on entend <b>n</b> : un-narbre<br>petit ours → on entend <b>t</b> : pe-ti-tour</p><p>Les mots gardent leur place, mais les sons se suivent plus facilement. On ne met pas de liaison partout.</p>", "chk": {"q": "Dans « les amis », j'entends…", "o": ["z", "n", "t"], "a": 0}}, {"t": "teach", "js": "lia", "mode": "son", "title": "Liaisons", "g": "les amis", "l": "z", "at": 1, "opts": ["z", "n", "t", "aucun son"], "ans": "z", "say": "les amis", "html": ""}, {"t": "teach", "js": "lia", "mode": "son", "title": "Liaisons", "g": "un arbre", "l": "n", "at": 1, "opts": ["z", "n", "t", "aucun son"], "ans": "n", "say": "un arbre", "html": ""}, {"t": "teach", "js": "lia", "mode": "son", "title": "Liaisons", "g": "petit ours", "l": "t", "at": 1, "opts": ["z", "n", "t", "aucun son"], "ans": "t", "say": "petit ours", "html": ""}, {"t": "teach", "js": "lia", "mode": "son", "title": "Liaisons", "g": "deux étoiles", "l": "z", "at": 1, "opts": ["z", "n", "t", "aucun son"], "ans": "z", "say": "deux étoiles", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "les amis", "l": "z", "at": 1, "say": "les amis", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "des oiseaux", "l": "z", "at": 1, "say": "des oiseaux", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "mes affaires", "l": "z", "at": 1, "say": "mes affaires", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "deux étoiles", "l": "z", "at": 1, "say": "deux étoiles", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "vous aimez", "l": "z", "at": 1, "say": "vous aimez", "html": ""}, {"t": "teach", "js": "lia", "mode": "pick", "title": "Liaisons", "q": "Écoute, puis touche le groupe où tu entends le son z.", "items": ["les amis", "le vélo", "une tortue"], "ans": 0, "say": "", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "un ami", "l": "n", "at": 1, "say": "un ami", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "un animal", "l": "n", "at": 1, "say": "un animal", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "mon école", "l": "n", "at": 1, "say": "mon école", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "ton idée", "l": "n", "at": 1, "say": "ton idée", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "petit arbre", "l": "t", "at": 1, "say": "petit arbre", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "grand ours", "l": "t", "at": 1, "say": "grand ours", "html": ""}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "cet avion", "l": "t", "at": 1, "say": "cet avion", "html": ""}, {"t": "sort", "q": "Range chaque groupe dans la bonne maison.", "cats": [{"k": "n", "label": "Son N", "cls": "g"}, {"k": "t", "label": "Son T", "cls": "v"}, {"k": "z", "label": "Son Z", "cls": "p"}], "items": [{"w": "un ami", "cat": "n", "hint": "Écoute le son qui relie les deux mots."}, {"w": "mon école", "cat": "n", "hint": "Écoute le son qui relie les deux mots."}, {"w": "ton idée", "cat": "n", "hint": "Écoute le son qui relie les deux mots."}, {"w": "petit arbre", "cat": "t", "hint": "Écoute le son qui relie les deux mots."}, {"w": "grand ours", "cat": "t", "hint": "Écoute le son qui relie les deux mots."}, {"w": "cet avion", "cat": "t", "hint": "Écoute le son qui relie les deux mots."}, {"w": "les amis", "cat": "z", "hint": "Écoute le son qui relie les deux mots."}, {"w": "des oiseaux", "cat": "z", "hint": "Écoute le son qui relie les deux mots."}, {"w": "deux étoiles", "cat": "z", "hint": "Écoute le son qui relie les deux mots."}]}, {"t": "teach", "js": "lia", "mode": "yn", "title": "Liaisons", "g": "les amis", "l": "z", "at": 1, "opts": ["J'entends un son qui relie les mots", "Je n'entends pas de liaison"], "ans": "J'entends un son qui relie les mots", "say": "les amis", "html": ""}, {"t": "teach", "js": "lia", "mode": "yn", "title": "Liaisons", "g": "un arbre", "l": "n", "at": 1, "opts": ["J'entends un son qui relie les mots", "Je n'entends pas de liaison"], "ans": "J'entends un son qui relie les mots", "say": "un arbre", "html": ""}, {"t": "teach", "js": "lia", "mode": "yn", "title": "Liaisons", "g": "le lapin", "l": "", "at": 1, "opts": ["J'entends un son qui relie les mots", "Je n'entends pas de liaison"], "ans": "Je n'entends pas de liaison", "say": "le lapin", "html": ""}, {"t": "teach", "js": "lia", "mode": "yn", "title": "Liaisons", "g": "deux ours", "l": "z", "at": 1, "opts": ["J'entends un son qui relie les mots", "Je n'entends pas de liaison"], "ans": "J'entends un son qui relie les mots", "say": "deux ours", "html": ""}, {"t": "teach", "js": "lia", "mode": "yn", "title": "Liaisons", "g": "la maison", "l": "", "at": 1, "opts": ["J'entends un son qui relie les mots", "Je n'entends pas de liaison"], "ans": "Je n'entends pas de liaison", "say": "la maison", "html": ""}, {"t": "build", "q": "Le train des mots : remets les mots dans l'ordre.", "words": ["ours.", "amis", "deux", "Les", "ont"], "ans": "Les amis ont deux ours.", "ok": "Bravo : « Les amis ont deux ours. »", "ko": "Commence par « Les »."}, {"t": "teach", "js": "lia", "mode": "rep", "title": "Liaisons", "g": "Les amis ont deux ours.", "multi": [[0, "z"], [1, "z"], [3, "z"]], "say": "Les amis ont deux ours.", "html": ""}]}]);

/* 2. La phrase : parcours CE1 */
window.MRX=window.MRX.concat([{"id": "ph-1", "name": "La phrase bien construite", "sub": "Majuscule, ordre des mots, signe final", "cls": "gn", "badge": "Aa", "steps": [{"t": "teach", "title": "La phrase bien construite", "say": "Une phrase commence par une majuscule et se termine par un signe de ponctuation.", "html": "<p class=\"big\">Une phrase commence par une <b>majuscule</b> et se termine par un <b>signe de ponctuation</b>.</p><p>Le chat dort.<br>Où est mon sac ?<br>Comme ce gâteau est bon !</p>", "chk": {"q": "Une phrase se termine par…", "o": ["une majuscule", "un signe de ponctuation"], "a": 1}}, {"t": "build", "q": "Remets les mots dans l'ordre.", "words": ["dort", "le", "chat"], "ans": "le chat dort", "ok": "Bravo : le chat dort", "ko": "Cherche d'abord qui fait l'action."}, {"t": "choice", "q": "Quel signe pour finir : « Le chat dort » ?", "opts": [". (point)", "? (point d'interrogation)", "! (point d'exclamation)"], "ans": 0, "ok": "Oui : Le chat dort.", "ko": "Relis bien la phrase."}, {"t": "build", "q": "Remets les mots dans l'ordre.", "words": ["sac", "où", "mon", "est"], "ans": "où est mon sac", "ok": "Bravo : où est mon sac", "ko": "Cherche d'abord qui fait l'action."}, {"t": "choice", "q": "Quel signe pour finir : « Où est mon sac » ?", "opts": [". (point)", "? (point d'interrogation)", "! (point d'exclamation)"], "ans": 1, "ok": "Oui : Où est mon sac ?", "ko": "Relis bien la phrase."}, {"t": "build", "q": "Remets les mots dans l'ordre.", "words": ["bon", "comme", "est", "gâteau", "ce"], "ans": "comme ce gâteau est bon", "ok": "Bravo : comme ce gâteau est bon", "ko": "Cherche d'abord qui fait l'action."}, {"t": "choice", "q": "Quel signe pour finir : « Comme ce gâteau est bon » ?", "opts": [". (point)", "? (point d'interrogation)", "! (point d'exclamation)"], "ans": 2, "ok": "Oui : Comme ce gâteau est bon !", "ko": "Relis bien la phrase."}, {"t": "choice", "q": "Laquelle est bien écrite ?", "opts": ["le chat dort.", "Le chat dort.", "Le chat dort"], "ans": 1, "ok": "Oui : Le chat dort. Majuscule au début, point à la fin.", "ko": "Relis bien la phrase."}]}, {"id": "ph-2", "name": "La phrase qui dit", "sub": "Dire, demander, s'exclamer", "cls": "gn", "badge": ".", "steps": [{"t": "teach", "title": "La phrase qui dit", "say": "Une phrase qui dit donne une information. Elle se termine souvent par un point. Le chien court dans le jardin.", "html": "<p class=\"big\">Une phrase qui <b>dit</b> donne une information. Elle se termine souvent par un <b>point</b>.</p><p>Le chien court dans le jardin.</p>", "chk": {"q": "Une phrase qui dit…", "o": ["pose une question", "donne une information"], "a": 1}}, {"t": "sort", "q": "Trie les phrases.", "cats": [{"k": "d", "label": "Elle dit", "cls": "g"}, {"k": "q", "label": "Elle demande", "cls": "v"}, {"k": "e", "label": "Elle s'exclame", "cls": "p"}], "items": [{"w": "Le chien court dans le jardin.", "cat": "d", "hint": "Regarde le signe à la fin."}, {"w": "Est-ce que le chien court ?", "cat": "q", "hint": "Regarde le signe à la fin."}, {"w": "Comme il court vite !", "cat": "e", "hint": "Regarde le signe à la fin."}]}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute la phrase, puis touche le bon panneau.", "w": "Le chien court dans le jardin.", "ans": "Elle dit", "opts": ["Elle dit", "Elle demande", "Elle s'exclame"], "say": "Le chien court dans le jardin.", "html": ""}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute la phrase, puis touche le bon panneau.", "w": "Est-ce que le chien court ?", "ans": "Elle demande", "opts": ["Elle dit", "Elle demande", "Elle s'exclame"], "say": "Est-ce que le chien court ?", "html": ""}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute la phrase, puis touche le bon panneau.", "w": "Comme il court vite !", "ans": "Elle s'exclame", "opts": ["Elle dit", "Elle demande", "Elle s'exclame"], "say": "Comme il court vite !", "html": ""}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute la phrase, puis touche le bon panneau.", "w": "Mon dessin est terminé.", "ans": "Elle dit", "opts": ["Elle dit", "Elle demande", "Elle s'exclame"], "say": "Mon dessin est terminé.", "html": ""}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute la phrase, puis touche le bon panneau.", "w": "Tu as vu mon crayon ?", "ans": "Elle demande", "opts": ["Elle dit", "Elle demande", "Elle s'exclame"], "say": "Tu as vu mon crayon ?", "html": ""}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute la phrase, puis touche le bon panneau.", "w": "Quel beau dessin !", "ans": "Elle s'exclame", "opts": ["Elle dit", "Elle demande", "Elle s'exclame"], "say": "Quel beau dessin !", "html": ""}]}, {"id": "ph-3", "name": "Le point d'interrogation et le point d'exclamation", "sub": "Ce que les signes indiquent", "cls": "gn", "badge": "?!", "steps": [{"t": "teach", "title": "Ce que les signes indiquent", "say": "Tu as vu mon crayon ? Je pose une question. Quel beau dessin ! Je m'exclame. Mon dessin est terminé. Je donne une information.", "html": "<p class=\"big\">Les signes indiquent ce que je veux dire.</p><p>Tu as vu mon crayon <b>?</b> → Je pose une question.<br>Quel beau dessin <b>!</b> → Je m'exclame.<br>Mon dessin est terminé<b>.</b> → Je donne une information.</p>", "chk": {"q": "Le point d'interrogation sert à…", "o": ["poser une question", "s'exclamer", "donner une information"], "a": 0}}, {"t": "choice", "q": "Ajoute le signe manquant : « Tu as vu mon crayon _ »", "opts": [". (point)", "? (point d'interrogation)", "! (point d'exclamation)"], "ans": 1, "ok": "Oui : Tu as vu mon crayon ?", "ko": "Relis bien la phrase."}, {"t": "choice", "q": "Ajoute le signe manquant : « Quel beau dessin _ »", "opts": [". (point)", "? (point d'interrogation)", "! (point d'exclamation)"], "ans": 2, "ok": "Oui : Quel beau dessin !", "ko": "Relis bien la phrase."}, {"t": "choice", "q": "Ajoute le signe manquant : « Mon dessin est terminé _ »", "opts": [". (point)", "? (point d'interrogation)", "! (point d'exclamation)"], "ans": 0, "ok": "Oui : Mon dessin est terminé.", "ko": "Relis bien la phrase."}, {"t": "match", "q": "Relie chaque phrase à ce qu'elle veut dire.", "pairs": [{"l": "Tu as vu mon crayon ?", "r": "Je pose une question"}, {"l": "Quel beau dessin !", "r": "Je m'exclame"}, {"l": "Mon dessin est terminé.", "r": "Je donne une information"}]}, {"t": "teach", "js": "lia", "lead": "Je lis à voix haute", "mode": "rep", "title": "Lecture", "g": "Tu as vu mon crayon ?", "say": "Tu as vu mon crayon ?", "html": ""}, {"t": "teach", "js": "lia", "lead": "Je lis à voix haute", "mode": "rep", "title": "Lecture", "g": "Quel beau dessin !", "say": "Quel beau dessin !", "html": ""}, {"t": "teach", "js": "lia", "lead": "Je lis à voix haute", "mode": "rep", "title": "Lecture", "g": "Mon dessin est terminé.", "say": "Mon dessin est terminé.", "html": ""}]}, {"id": "ph-4", "name": "La phrase affirmative et la phrase négative", "sub": "ne… pas", "cls": "gn", "badge": "ne", "steps": [{"t": "teach", "title": "Affirmative ou négative ?", "say": "Une phrase affirmative dit que quelque chose se passe. Une phrase négative dit que cela ne se passe pas. Dans une phrase négative, ne et pas encadrent généralement le verbe. Le chat dort : phrase affirmative. Le chat ne dort pas : phrase négative. Lina aime les épinards : phrase affirmative. Lina n'aime pas les épinards : phrase négative.", "html": "<p class=\"big\">Une phrase <b>affirmative</b> dit que quelque chose se passe. Une phrase <b>négative</b> dit que cela ne se passe pas.</p><p>Dans une phrase négative, <b>ne… pas</b> encadre généralement le verbe.</p><p>Le chat dort. → affirmative<br>Le chat <b>ne</b> dort <b>pas</b>. → négative</p><p>Lina aime les épinards. → affirmative<br>Lina <b>n'</b>aime <b>pas</b> les épinards. → négative</p>", "chk": {"q": "« Le chat ne dort pas. » Cette phrase est…", "o": ["affirmative", "négative"], "a": 1}}, {"t": "teach", "title": "Devant une voyelle", "say": "Point d'attention : devant une voyelle, ne devient n apostrophe. Il n'aime pas le bruit.", "html": "<p class=\"big\">Devant une voyelle, <b>ne</b> devient <b>n'</b>.</p><p>Il <b>n'</b>aime <b>pas</b> le bruit.</p>", "chk": {"q": "Devant « aime », ne devient…", "o": ["n'", "ne", "pas"], "a": 0}}, {"t": "build", "q": "Transforme : « Le lapin mange. » devient négative.", "words": ["mange", "Le", "pas.", "ne", "lapin"], "ans": "Le lapin ne mange pas.", "ok": "Bravo : Le lapin ne mange pas.", "ko": "Cherche d'abord qui fait l'action."}, {"t": "build", "q": "Transforme : « Le chat dort. » devient négative.", "words": ["dort", "ne", "Le", "chat", "pas."], "ans": "Le chat ne dort pas.", "ok": "Bravo : Le chat ne dort pas.", "ko": "Cherche d'abord qui fait l'action."}, {"t": "choice", "q": "Complète : « Milo ___ court ___. »", "opts": ["ne … pas", "pas … ne", "ne … ne"], "ans": 0, "ok": "Oui : Milo ne court pas.", "ko": "Relis bien la phrase."}, {"t": "tapmany", "q": "Touche ne, le verbe et pas.", "tokens": ["Milo", "ne", "court", "pas."], "ans": [1, 2, 3], "ok": "Oui : ne… pas encadre le verbe court."}, {"t": "tapmany", "q": "Touche ne, le verbe et pas.", "tokens": ["Le", "chat", "ne", "dort", "pas."], "ans": [2, 3, 4], "ok": "Oui : ne… pas encadre le verbe dort."}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute : la phrase est-elle affirmative ou négative ?", "w": "Le chat ne dort pas.", "ans": "Négative", "opts": ["Affirmative", "Négative"], "say": "Le chat ne dort pas.", "html": ""}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute : la phrase est-elle affirmative ou négative ?", "w": "Lina aime les épinards.", "ans": "Affirmative", "opts": ["Affirmative", "Négative"], "say": "Lina aime les épinards.", "html": ""}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute : la phrase est-elle affirmative ou négative ?", "w": "Il n'aime pas le bruit.", "ans": "Négative", "opts": ["Affirmative", "Négative"], "say": "Il n'aime pas le bruit.", "html": ""}, {"t": "teach", "js": "dic", "lead": "Écoute", "title": "Écoute", "mode": "p", "q": "Écoute : la phrase est-elle affirmative ou négative ?", "w": "Le lapin mange.", "ans": "Affirmative", "opts": ["Affirmative", "Négative"], "say": "Le lapin mange.", "html": ""}, {"t": "choice", "q": "Laquelle est bien écrite ?", "opts": ["Il ne aime pas le bruit.", "Il n'aime pas le bruit."], "ans": 1, "ok": "Oui : Il n'aime pas le bruit. Devant une voyelle, ne devient n'.", "ko": "Relis bien la phrase."}]}, {"id": "ph-def", "name": "Mini-défi : à quoi sert la phrase ?", "sub": "Son intention et sa forme", "cls": "gn", "badge": "🏆", "steps": [{"t": "sort", "q": "Classe selon l'intention : à quoi sert la phrase ?", "cats": [{"k": "d", "label": "Elle dit", "cls": "g"}, {"k": "q", "label": "Elle demande", "cls": "v"}, {"k": "e", "label": "Elle s'exclame", "cls": "p"}], "items": [{"w": "Le dragon dort.", "cat": "d", "hint": "Regarde le signe à la fin."}, {"w": "Le dragon ne dort pas.", "cat": "d", "hint": "Regarde le signe à la fin."}, {"w": "Le dragon dort-il ?", "cat": "q", "hint": "Regarde le signe à la fin."}, {"w": "Comme ce dragon est grand !", "cat": "e", "hint": "Regarde le signe à la fin."}]}, {"t": "sort", "q": "Classe selon la forme : affirmative ou négative ?", "cats": [{"k": "a", "label": "Affirmative", "cls": "g"}, {"k": "n", "label": "Négative", "cls": "v"}], "items": [{"w": "Le dragon dort.", "cat": "a", "hint": "Cherche ne… pas."}, {"w": "Le dragon ne dort pas.", "cat": "n", "hint": "Cherche ne… pas."}, {"w": "Le dragon dort-il ?", "cat": "a", "hint": "Cherche ne… pas."}, {"w": "Comme ce dragon est grand !", "cat": "a", "hint": "Cherche ne… pas."}]}]}]);

