  w.addEventListener('pointermove',function(e){if(!dr)return;if(!dr[4]&&Math.abs(e.clientX-dr[0])+Math.abs(e.clientY-dr[1])<10)return;dr[4]=1;var ry=Math.max(-40,Math.min(40,dr[3]+(e.clientX-dr[0])*.35)),rx=Math.max(0,Math.min(60,dr[2]-(e.clientY-dr[1])*.35));c3.dataset.rx=rx;c3.dataset.ry=ry;c3.style.transform='scale('+c3.dataset.k+') rotateX('+rx+'deg) rotateY('+ry+'deg)';if(!run)mrClkFrog(c,me.vis,0,0)});
