/* Fractions : bande à partager / colorier, droite graduée avec Craplave */
(function(){try{var st=document.createElement('style');st.textContent='.wcut svg,.wfl svg{display:block;margin:0 auto;max-width:100%;touch-action:manipulation}.wcut .msg,.wfl .msg{text-align:center;font-weight:800;min-height:1.4em}.wcut .part{transition:fill .25s}.wcut .part.on{animation:mr-stamp .4s!important}.wfl .wl-in{position:relative;display:block;max-width:360px;margin:0 auto}.wfl .mk{animation:mr-stamp .45s!important}';document.head.appendChild(st)}catch(e){}})();
MRW['w-cut']=function(){var s=M[cur.m].steps[cur.i],box=document.getElementById('mrw');if(!box)return;mrGate(false);
  var paint=!!s.paint,n=paint?s.n:8,X0=20,Wd=300,Y=34,Hh=50,done=false,cuts=[],col=[],msg='';
  var cw=Wd/n;
  var draw=function(){var h='<div class="wcut"><svg viewBox="0 0 340 120" width="100%" style="max-width:380px"><rect x="'+(X0+4)+'" y="'+(Y+8)+'" width="'+Wd+'" height="'+Hh+'" rx="12" fill="rgba(27,35,71,.2)"/>';
    var edges=paint?[]:[0].concat(cuts.slice().sort(function(a,b){return a-b}),[8]);
    if(paint){for(var i=0;i<n;i++){var on=col.indexOf(i)>=0;h+='<rect class="part'+(on?' on':'')+'" data-p="'+i+'" x="'+(X0+i*cw)+'" y="'+Y+'" width="'+cw+'" height="'+Hh+'" fill="'+(on?'#e0393f':'#ffd98a')+'" stroke="#fff" stroke-width="4" style="cursor:pointer"/>'}}
    else{for(i=0;i<edges.length-1;i++){h+='<rect class="part'+(done?' on':'')+'" x="'+(X0+edges[i]*Wd/8)+'" y="'+Y+'" width="'+((edges[i+1]-edges[i])*Wd/8)+'" height="'+Hh+'" fill="'+(done?['#ffd98a','#ffb347'][i%2]:'#ffd98a')+'" stroke="#fff" stroke-width="'+(i?4:0)+'"/>'}
      for(i=1;i<8;i++)h+='<line x1="'+(X0+i*Wd/8)+'" y1="'+(Y+Hh)+'" x2="'+(X0+i*Wd/8)+'" y2="'+(Y+Hh+8)+'" stroke="#5b6491" stroke-width="2"/>';
      for(i=1;i<8;i++){var on2=cuts.indexOf(i)>=0;if(!on2)h+='<line x1="'+(X0+i*Wd/8)+'" y1="'+Y+'" x2="'+(X0+i*Wd/8)+'" y2="'+(Y+Hh)+'" stroke="#c9a24a" stroke-width="1.5" stroke-dasharray="3 4"/>';else h+='<line x1="'+(X0+i*Wd/8)+'" y1="'+(Y-6)+'" x2="'+(X0+i*Wd/8)+'" y2="'+(Y+Hh+6)+'" stroke="#2459e6" stroke-width="5" stroke-linecap="round"/>'}}
    h+='<rect x="'+X0+'" y="'+Y+'" width="'+Wd+'" height="'+Hh+'" rx="12" fill="none" stroke="#c98a00" stroke-width="4"/>';
    if(!paint&&!done)for(i=1;i<8;i++)h+='<rect data-c="'+i+'" x="'+(X0+i*Wd/8-16)+'" y="'+(Y-12)+'" width="32" height="'+(Hh+24)+'" fill="transparent" style="cursor:pointer"/>';
    h+='</svg><p class="msg">'+msg+'</p></div>'+(done?fbBox('ok',paint?'Bravo : '+s.paint+' part sur '+n+' = 1/'+n+' !':'Bravo : '+(s.need.length+1)+' parts égales !'):'');
    box.innerHTML=h;
    box.querySelectorAll('[data-c]').forEach(function(r){r.onclick=function(){if(done)return;var c=+r.dataset.c,k=cuts.indexOf(c);if(k>=0)cuts.splice(k,1);else cuts.push(c);msg='';
      if(cuts.length===s.need.length){var a=cuts.slice().sort(function(x,y){return x-y}).join(),b=s.need.join();if(a===b){done=true;mrGate(true)}else{msg='Les parts ne sont pas égales : compte les carreaux !';draw();setTimeout(function(){if(!done){cuts=[];msg='';draw()}},1500);return}}
      else if(cuts.length>s.need.length){msg='Trop de séparations !'}
      draw()}});
    box.querySelectorAll('[data-p]').forEach(function(r){r.onclick=function(){if(done)return;var p=+r.dataset.p,k=col.indexOf(p);if(k>=0)col.splice(k,1);else col.push(p);msg='';
      if(col.length===s.paint){done=true;mrGate(true)}else if(col.length>s.paint){col=[p];msg='Une seule part !'}
      draw()}})};
  draw()};
MRW['w-fl']=function(){var s=M[cur.m].steps[cur.i],box=document.getElementById('mrw');if(!box)return;mrGate(false);
  var n=s.n,X0=30,L=300,Wd=360,idx=0,placed=[],msg='',done=false,ghost=s.ghost||null,pos=0,run=false;
  var X=function(i){return X0+i*L/n};
  box.innerHTML='<div class="wfl"><div class="wl-in"><svg id="wfs" viewBox="0 0 '+Wd+' 130" width="'+Wd+'"></svg><div class="wl-f3" id="wff"><div class="wl-fs"></div>'+mrFrogH+'</div></div><p class="msg" id="wfm"></p><div id="wfu"></div></div>';
  var svg=document.getElementById('wfs'),f=document.getElementById('wff'),fb=f.querySelector('.f3'),fs=f.querySelector('.wl-fs'),mm=document.getElementById('wfm'),u=document.getElementById('wfu');
  var place=function(x,lift,sq){var k=(svg.getBoundingClientRect().width||Wd)/Wd;f.style.transform='translate('+(x*k).toFixed(1)+'px,'+(88*k).toFixed(1)+'px) scale('+(.72*k).toFixed(3)+')';fb.style.transform='translateY('+(-lift).toFixed(1)+'px) scale('+(1+sq*.25)+','+(1-sq*.3)+')';var q=1-lift/120;fs.style.transform='scale('+q.toFixed(2)+')';fs.style.opacity=q};
  var hop=function(to,cb){var a=X(pos),z=X(to),s0=performance.now();run=true;(function h(now){var p=Math.min(1,(now-s0)/600),pre=.14,q=p<pre?0:(p-pre)/(1-pre),e=q<.5?2*q*q:1-Math.pow(-2*q+2,2)/2;place(a+(z-a)*e,Math.sin(Math.PI*q)*70,p<pre?p/pre:p>.9?(1-p)*9:-.35*Math.sin(Math.PI*q));if(p<1)requestAnimationFrame(h);else{pos=to;place(z,0,0);run=false;if(cb)cb()}})(s0)};
  var draw=function(){var h='<rect x="'+X0+'" y="94" width="'+L+'" height="8" rx="4" fill="#5b6491"/><rect x="'+X0+'" y="94" width="'+(done?L:(placed.length?(X(placed[placed.length-1].t)-X0):0))+'" height="8" rx="4" fill="#0e9a63" opacity=".55"/>';
    for(var i=0;i<=n;i++)h+='<line x1="'+X(i)+'" y1="86" x2="'+X(i)+'" y2="110" stroke="#1b2347" stroke-width="'+(i===0||i===n?4:2.5)+'"/>';
    h+='<text x="'+X(0)+'" y="128" text-anchor="middle" font-size="18" font-weight="800" fill="#1b2347">0</text><text x="'+X(n)+'" y="128" text-anchor="middle" font-size="18" font-weight="800" fill="#1b2347">1</text>';
    if(ghost)h+='<g opacity=".6"><circle cx="'+X(ghost.t)+'" cy="76" r="5" fill="#e0393f"/><text x="'+X(ghost.t)+'" y="26" text-anchor="middle" font-size="16" font-weight="800" fill="#e0393f">'+ghost.l+'</text></g>';
    placed.forEach(function(p){h+='<g class="mk"><circle cx="'+X(p.t)+'" cy="76" r="5" fill="#0e9a63"/><text x="'+X(p.t)+'" y="26" text-anchor="middle" font-size="16" font-weight="800" fill="#0e9a63">'+p.l+'</text></g>'});
    if(!done)for(i=0;i<=n;i++)h+='<circle data-t="'+i+'" cx="'+X(i)+'" cy="100" r="'+Math.min(18,L/n/2)+'" fill="transparent" style="cursor:pointer"/>';
    svg.innerHTML=h;mm.innerHTML=msg||(done?'':(s.seq[idx].ask||('Touche '+s.seq[idx].l)));
    u.innerHTML=done?fbBox('ok','Bravo, tu as bien placé '+(s.seq.length>1?'les repères':s.seq[0].l)+' !'):'';
    svg.querySelectorAll('[data-t]').forEach(function(c){c.onclick=function(){if(done||run)return;var t=+c.dataset.t,g=s.seq[idx];
      if(t===g.t){msg='';ghost=null;hop(t,function(){placed.push(g);if(s.seq.length>1||true){}idx++;if(idx>=s.seq.length){done=true;mrGate(true)}draw()})}
      else{msg='Pas tout à fait : compte les parts depuis le 0.';draw();fbHint()}}})};
  var fbHint=function(){try{u.innerHTML=fbBox('ko','Compte les parts égales depuis le 0, puis touche le bon repère.')}catch(e){}};
  place(X(0),0,0);draw()};
MRW['w-sent']=function(){var s=M[cur.m].steps[cur.i],box=document.getElementById('mrw');if(!box)return;
  var h='<button class="btn" id="wsall" style="margin:4px 0 10px">🔊 Tout écouter</button>';
  s.sents.forEach(function(t,k){h+='<button class="mr-sent" data-s="'+k+'" style="display:block;width:100%;text-align:left;padding:10px 12px;margin:6px 0;border:2px solid #cfd6f2;border-radius:14px;background:#fff;font:700 1rem var(--body,inherit);color:#1b2347;cursor:pointer">🔊 '+esc(t)+'</button>'});
  box.innerHTML=h;
  var mark=function(k){box.querySelectorAll('.mr-sent').forEach(function(b,i){b.style.background=i===k?'#fff3c4':'#fff';b.style.borderColor=i===k?'#ffc21a':'#cfd6f2'})};
  box.querySelectorAll('.mr-sent').forEach(function(b){b.onclick=function(){mark(+b.dataset.s);say(s.sents[+b.dataset.s])}});
  document.getElementById('wsall').onclick=function(){mark(0);say(s.sents.join(' '))}};
MRW['w-place']=function(){var s=M[cur.m].steps[cur.i],box=document.getElementById('mrw');if(!box)return;mrGate(false);
  var k=0,msg='',pos=null,busy=false;var Z={'devant':[40,70],'derrière':[42,24],'loin':[84,8],'près':[68,52]};
  var bad=function(n){window.mrBil=window.mrBil||{};mrBil[n]=(mrBil[n]||0)+1;if(window.mrRemErr)mrRemErr(n)};
  var draw=function(){if(!box.isConnected)return;var t=s.tasks[k],h='<p style="font-weight:800;font-size:1.15rem;margin:4px 0 8px">'+esc(t.ask)+' <button id="plsay" style="font-size:1.1rem">🔊</button></p><div style="position:relative;height:210px;border-radius:18px;background:linear-gradient(#bfe6ff 0 42%,#9ad37a 42% 100%);overflow:hidden;box-shadow:inset 0 -6px 0 rgba(0,0,0,.08)">';
    h+='<div style="position:absolute;left:38%;top:32%;font-size:66px;z-index:3;line-height:1;filter:drop-shadow(0 4px 3px rgba(0,0,0,.25))">'+t.o+'</div>';
    Object.keys(Z).forEach(function(z){var p=Z[z];h+='<button data-z="'+z+'" aria-label="'+z+'" style="position:absolute;left:'+p[0]+'%;top:'+p[1]+'%;width:58px;height:58px;border-radius:50%;border:3px dashed rgba(27,35,71,.3);background:rgba(255,255,255,.3);z-index:4;cursor:pointer"></button>'});
    if(pos){var p=Z[pos];h+='<div style="position:absolute;left:'+(p[0]+2)+'%;top:'+(p[1]+3)+'%;font-size:'+(pos==='loin'?26:42)+'px;z-index:'+(pos==='derrière'?2:5)+';pointer-events:none;animation:mrpop .4s">🧒</div>'}
    h+='</div><p style="min-height:1.5em;font-weight:800;margin-top:8px">'+msg+'</p>';box.innerHTML=h;
    document.getElementById('plsay').onclick=function(){say(t.ask)};
    box.querySelectorAll('[data-z]').forEach(function(b){b.onclick=function(){if(busy)return;var z=b.dataset.z;
      if(z===t.z){busy=true;pos=z;msg='Bravo ! Rico est '+z+'.';draw();setTimeout(function(){pos=null;msg='';k++;busy=false;if(k>=s.tasks.length){box.innerHTML='<p style="font-weight:800;font-size:1.2rem">Bravo, tu as placé Rico quatre fois ! 🎉</p>';mrGate(true)}else draw()},900)}
      else{bad('Mot invariable mal mémorisé');pos=z;msg='Pas ici. '+t.hint;draw();setTimeout(function(){pos=null;draw()},900)}}});
  };draw();setTimeout(function(){say(s.tasks[0].ask)},300)};
MRW['w-copy']=function(){var s=M[cur.m].steps[cur.i],box=document.getElementById('mrw');if(!box)return;mrGate(false);
  var IVN='Mot invariable mal mémorisé',CPN='Mot ou groupe de mots oublié en copie',PNN='Ponctuation, majuscule ou espaces oubliés';
  var tries=0,phase=s.vis?'write':'look',typed='';
  var nz=function(x){return String(x).replace(/[’`]/g,"'")};
  var tok=function(x){var t=nz(x).trim();return t?t.split(/\s+/):[]};
  var sp=function(w){return w.replace(/[.,;:!?«»"]/g,'').toLowerCase()};
  var bad=function(n){window.mrBil=window.mrBil||{};mrBil[n]=(mrBil[n]||0)+1;if(window.mrRemErr)mrRemErr(n)};
  var frag=function(w,ok){try{var k='mr-fragile',f=JSON.parse(localStorage.getItem(k)||'{}');if(ok){if(f[w])f[w]--;if(f[w]<=0)delete f[w]}else f[w]=(f[w]||0)+1;localStorage.setItem(k,JSON.stringify(f))}catch(e){}};
  var COL=['#2563eb','#e0393f','#0e9a63','#b8860b'];
  var modelH=function(){var g=s.groups||[s.model];return '<div style="background:#fff;border:3px solid #cfd6f2;border-radius:16px;padding:12px 14px;font:800 1.25rem/1.7 var(--display,inherit)">'+g.map(function(x,i){return '<span style="color:'+COL[i%4]+';border-bottom:3px solid '+COL[i%4]+';margin-right:6px;display:inline-block">'+esc(x)+'</span>'}).join(' ')+'</div>'};
  var analyse=function(v){var raw=nz(v).trim(),mod=nz(s.model);if(raw===mod)return{ok:1};
    var m=tok(mod),t=tok(raw),ts=t.map(sp),ms=m.map(sp),inv=(s.inv||[]).map(function(x){return nz(x).toLowerCase()}),cats=[],msg=[],miss=[];
    m.forEach(function(w,i){if(ts.indexOf(ms[i])<0)miss.push(w)});
    miss.forEach(function(w){if(inv.indexOf(sp(w))>=0){cats.push(IVN);frag(sp(w),false);msg.push('Regarde bien le mot « '+w.replace(/[.,]/g,'')+' ».')}else{cats.push(CPN);msg.push('Un mot ou un groupe n\'est pas bien copié : « '+w+' ».')}});
    if(!miss.length&&t.length>m.length){cats.push(CPN);msg.push('Il y a un mot en trop.')}
    if(!miss.length&&t.length===m.length&&mod!==t.join(' ')){cats.push(PNN);msg.push('Vérifie la majuscule, la ponctuation et les espaces.')}
    else if(!cats.length||(!miss.length&&/\s{2,}/.test(raw))){cats.push(PNN);msg.push('Vérifie les espaces, la majuscule et la ponctuation.')}
    return{ok:0,cats:cats,msg:msg,m:m,ts:ts,ms:ms}};
  var draw=function(){if(!box.isConnected)return;var h='';
    if(phase==='look'){h=modelH()+'<div class="dic-row" style="margin:10px 0"><button id="cpsay">🔊 Écouter</button><button class="go" id="cphide">Je cache et j\'écris 🙈</button></div>'}
    else if(phase==='write'){h=(s.vis?modelH():'<div style="background:#eef1ff;border:3px dashed #cfd6f2;border-radius:16px;padding:14px;font-weight:800;text-align:center">🙈 Le modèle est caché. Écris de mémoire.</div>')+'<textarea id="cpin" class="dic-in" rows="'+(s.model.length>34?3:1)+'" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" placeholder="J\'écris ici" style="margin-top:10px;width:100%;resize:none">'+esc(typed)+'</textarea><div class="dic-row" style="margin-top:8px"><button class="go" id="cpok">Vérifier</button>'+(s.vis?'':'<button id="cpsee">👀 Revoir le modèle</button>')+'</div>'}
    else{var r=analyse(typed);
      if(r.ok){h=modelH()+fbBox('ok','Bravo : ta copie est exacte !');mrGate(true)}
      else{var last=tries>=2;
        h=(last?'<p style="font-weight:800;margin:4px 0">Le modèle :</p>'+modelH():'')+'<p style="font-weight:800;margin:8px 0 2px">Ta copie :</p><div style="background:#fff;border:3px solid #e0393f55;border-radius:16px;padding:12px;font:800 1.1rem/1.6 var(--display,inherit)">'+(esc(typed)||'…')+'</div>'+fbBox('ko',r.msg.join(' ')+(last?' Voici le modèle : on le retrouvera plus tard.':' Regarde le modèle et réessaie.'));
        if(!last)h+='<div class="dic-row" style="margin-top:8px"><button class="go" id="cpre">Je réessaie</button></div>';else mrGate(true)}}
    box.innerHTML=h;
    var q=function(id){return document.getElementById(id)};
    if(q('cpsay'))q('cpsay').onclick=function(){say(s.model)};
    if(q('cphide'))q('cphide').onclick=function(){phase='write';draw()};
    if(q('cpsee'))q('cpsee').onclick=function(){typed=q('cpin').value;phase='look';draw()};
    if(q('cpre'))q('cpre').onclick=function(){phase=s.vis?'write':'look';draw()};
    if(q('cpok'))q('cpok').onclick=function(){var v=q('cpin').value;if(!v.trim())return;typed=v;tries++;phase='res';var r=analyse(v);if(!r.ok){var u={};r.cats.forEach(function(c){if(!u[c]){u[c]=1;bad(c)}})}draw()};
    var ci=q('cpin');if(ci)ci.onkeydown=function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();q('cpok').click()}};
  };draw()};
MRW['w-cal']=function(){var s=M[cur.m].steps[cur.i],box=document.getElementById('mrw');if(!box)return;if(s.target)mrGate(false);
  var CM=window.mrCalM||{y:2026,m:10},MN=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'],nm=MN[CM.m],nd=new Date(CM.y,CM.m+1,0).getDate(),
  J=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'],off=(new Date(CM.y,CM.m,1).getDay()+6)%7,sel=0,done=false;
  var draw=function(){var h='<div class="wc"><h4>'+nm.charAt(0).toUpperCase()+nm.slice(1)+'</h4><div class="g">'+['L','M','M','J','V','S','D'].map(function(x){return '<b>'+x+'</b>'}).join('');
    for(var i=0;i<off;i++)h+='<span></span>';for(var d=1;d<=nd;d++)h+='<button data-d="'+d+'" class="'+(d===sel?(done?'win':'on'):'')+'">'+d+'</button>';
    h+='</div></div><p class="wc-say">'+(sel?J[(off+sel-1)%7]+' '+sel+' '+nm+(done?' 🎉':''):'Touche un jour')+'</p>'+(done?fbBox('ok','Bravo, tu as trouvé la date !'):s.target&&sel?fbBox('ko','Ce n\'est pas le bon jour. Cherche la colonne du jour, puis le nombre.'):'');
    box.innerHTML=h;box.querySelectorAll('[data-d]').forEach(function(b){b.onclick=function(){if(done)return;sel=+b.dataset.d;if(s.target&&sel===s.target){done=true;mrGate(true)}draw()}})};
  draw()};

/* Calendrier : le mois en cours (jours, dates et textes suivent la date de l'appareil) */
(function(){var d=new Date(),y=d.getFullYear(),mo=d.getMonth();
 window.mrCalM={y:y,m:mo};
 var MN=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'],
 W=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'];
 var mm=function(add){var t=mo+add;return {y:y+Math.floor(t/12),m:((t%12)+12)%12}};
 var map=function(w,dd,M){var wi=W.indexOf(w.toLowerCase()),fi=(new Date(M.y,M.m,1).getDay()+6)%7;return ((wi-fi)%7+7)%7+1+7*Math.floor((dd-1)/7)};
 var cur={y:y,m:mo},sor=mm(3),vis=mm(6);
 var WD='(lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche)';
 var PA=new RegExp(WD+' (\\d{1,2}) (novembre|mars|mai)','gi');
 var tgt=function(mn){return mn==='novembre'?cur:mn==='mars'?sor:vis};
 var tr=function(str){var ds={},r=str.replace(PA,function(a,w,dd,mn){var M=tgt(mn.toLowerCase()),n=map(w,+dd,M);if(mn.toLowerCase()==='novembre')ds[dd]=n;return w+' '+n+' '+MN[M.m]});
  r=r.replace(/(date → |la date est le )(\\d+)/g,function(a,b,n){return b+(ds[n]!==undefined?ds[n]:n)});
  return r.replace(/mois est novembre/g,'mois est '+MN[cur.m]).replace(/mois → novembre/g,'mois → '+MN[cur.m]).replace(/en novembre/g,'en '+MN[cur.m])};
 var walk=function(o){if(!o||typeof o!=='object')return;
  if(o.js==='w-cal'&&typeof o.say==='string'){var m=new RegExp(WD+' (\\d{1,2}) novembre','i').exec(o.say);if(m&&o.target)o.target=map(m[1],+m[2],cur)}
  Object.keys(o).forEach(function(k){var v=o[k];if(typeof v==='string'){if(/novembre|mars|mai|date/.test(v))o[k]=tr(v)}else if(v&&typeof v==='object')walk(v)})};
 window.mrCalWalk=walk})();

/* Case 18 : l'heure */
window.MRX=window.MRX.concat([{"id": "he-1", "name": "Les aiguilles de l'horloge", "sub": "Heures et minutes", "cls": "gn", "badge": "🕓", "steps": [{"t": "teach", "title": "Les deux aiguilles", "say": "Sur une horloge à aiguilles, la petite aiguille indique les heures. La grande aiguille indique les minutes. Fais tourner l'horloge : la petite avance lentement pendant que la grande fait le tour du cadran.", "html": "<p class=\"big\">La <b style='color:#e0393f'>petite aiguille</b> indique les <b>heures</b>.<br>La <b style='color:#2459e6'>grande aiguille</b> indique les <b>minutes</b>.</p><div id=\"mrw\"></div><p>La petite avance lentement pendant que la grande fait le tour du cadran.</p>", "js": "w-clk", "chk": {"q": "La grande aiguille indique…", "o": ["les minutes", "les heures"], "a": 0}}, {"t": "teach", "title": "De 5 en 5", "say": "La grande aiguille avance de 5 minutes à chaque nombre. Sur le 1 : 5 minutes. Sur le 2 : 10 minutes. Sur le 3 : 15 minutes. Sur le 6 : 30 minutes. Sur le 9 : 45 minutes. Sur le 12 : 0 minute, c'est une heure entière.", "html": "<p class=\"big\">La grande aiguille avance de <b>5 minutes à chaque nombre</b>.</p><div class=\"ckw\"><div data-clk=\"-:30\" data-sz=\"190\"></div></div><p>sur le 1 : 5 min · sur le 2 : 10 min · sur le 3 : 15 min<br>sur le 6 : 30 min · sur le 9 : 45 min<br>sur le 12 : 0 minute, une <b>heure entière</b></p>", "js": "w-anim", "chk": {"q": "Grande aiguille sur le 3, c'est…", "o": ["15 minutes", "3 minutes"], "a": 0}}, {"t": "teach", "title": "Je lis l'heure", "say": "La petite aiguille est sur le 4 et la grande sur le 12 : il est 4 heures. La petite aiguille vient de dépasser le 4 et la grande est sur le 6 : il est 4 heures et 30 minutes, ou 4 heures et demie.", "html": "<div class=\"ckrow\"><div class=\"ckw\"><div data-clk=\"4:0\" data-sz=\"138\"></div><b>4 h</b></div><div class=\"ckw\"><div data-clk=\"4:30\" data-sz=\"138\"></div><b>4 h 30</b></div></div><p style=\"text-align:center;font-weight:800\"><span style=\"color:#e0393f\">● petite aiguille : heures</span> · <span style=\"color:#2459e6\">● grande aiguille : minutes</span></p><p>Petite sur le 4, grande sur le 12 : <b>4 heures</b>.<br>Petite juste après le 4, grande sur le 6 : <b>4 heures et demie</b>.</p>", "js": "w-anim", "chk": {"q": "Grande aiguille sur le 12, c'est…", "o": ["une heure entière", "une demi-heure"], "a": 0}}, {"t": "teach", "js": "w-clk", "mode": "hand", "title": "Quelle aiguille ?", "say": "Touche l'aiguille des heures.", "html": "<p class=\"big\">Touche l'aiguille des heures.</p><div id=\"mrw\"></div>", "want": "h"}, {"t": "teach", "js": "w-clk", "mode": "hand", "title": "Quelle aiguille ?", "say": "Touche l'aiguille des minutes.", "html": "<p class=\"big\">Touche l'aiguille des minutes.</p><div id=\"mrw\"></div>", "want": "m"}, {"t": "teach", "js": "w-pick", "title": "Compte les minutes", "say": "La grande aiguille est sur le 2. Combien de minutes ?", "html": "<p class=\"big\">La grande aiguille est sur le 2. Combien de minutes ?</p><div class=\"ckw\"><div data-clk=\"-:10\" data-sz=\"190\"></div></div><div id=\"mrw\"></div>", "opts": ["2 minutes", "10 minutes", "20 minutes"], "ans": 1, "ok": "Oui : 10 minutes.", "ko": "Compte de 5 en 5 : 5, 10…"}, {"t": "teach", "js": "w-pick", "title": "Compte les minutes", "say": "La grande aiguille est sur le 4. Combien de minutes ?", "html": "<p class=\"big\">La grande aiguille est sur le 4. Combien de minutes ?</p><div class=\"ckw\"><div data-clk=\"-:20\" data-sz=\"190\"></div></div><div id=\"mrw\"></div>", "opts": ["4 minutes", "20 minutes", "40 minutes"], "ans": 1, "ok": "Oui : 20 minutes.", "ko": "Compte de 5 en 5."}, {"t": "teach", "js": "w-pick", "title": "Compte les minutes", "say": "La grande aiguille est sur le 6. Combien de minutes ?", "html": "<p class=\"big\">La grande aiguille est sur le 6. Combien de minutes ?</p><div class=\"ckw\"><div data-clk=\"-:30\" data-sz=\"190\"></div></div><div id=\"mrw\"></div>", "opts": ["6 minutes", "30 minutes", "60 minutes"], "ans": 1, "ok": "Oui : 30 minutes.", "ko": "Compte de 5 en 5."}, {"t": "teach", "js": "w-pick", "title": "Compte les minutes", "say": "La grande aiguille est sur le 10. Combien de minutes ?", "html": "<p class=\"big\">La grande aiguille est sur le 10. Combien de minutes ?</p><div class=\"ckw\"><div data-clk=\"-:50\" data-sz=\"190\"></div></div><div id=\"mrw\"></div>", "opts": ["10 minutes", "45 minutes", "50 minutes"], "ans": 2, "ok": "Oui : 50 minutes.", "ko": "Compte de 5 en 5."}, {"t": "teach", "js": "w-pick", "title": "Lis l'heure", "say": "Quelle heure est-il ?", "html": "<p class=\"big\">Quelle heure est-il ?</p><div class=\"ckw\"><div data-clk=\"7:0\" data-sz=\"190\"></div></div><div id=\"mrw\"></div>", "opts": ["7 h", "12 h", "7 h 30"], "ans": 0, "ok": "Oui : 7 h.", "ko": "Regarde bien les aiguilles."}, {"t": "teach", "js": "w-pick", "title": "Lis l'heure", "say": "Quelle heure est-il ?", "html": "<p class=\"big\">Quelle heure est-il ?</p><div class=\"ckw\"><div data-clk=\"2:30\" data-sz=\"190\"></div></div><div id=\"mrw\"></div>", "opts": ["6 h 10", "2 h 30", "3 h 30"], "ans": 1, "ok": "Oui : 2 h 30.", "ko": "La petite aiguille vient de dépasser le 2."}, {"t": "teach", "js": "w-pick", "title": "Lis l'heure", "say": "Quelle heure est-il ?", "html": "<p class=\"big\">Quelle heure est-il ?</p><div class=\"ckw\"><div data-clk=\"9:15\" data-sz=\"190\"></div></div><div id=\"mrw\"></div>", "opts": ["9 h 15", "3 h 45", "9 h 03"], "ans": 0, "ok": "Oui : 9 h 15.", "ko": "La grande aiguille sur le 3, c'est 15 minutes."}, {"t": "teach", "js": "w-clk", "mode": "set", "title": "Construis l'heure", "say": "Règle l'horloge : il est 5 h 30.", "html": "<p class=\"big\">🃏 Il est <b>5 h 30</b>. Règle l'horloge !</p><div id=\"mrw\"></div>", "h": 5, "m": 30}, {"t": "choice", "q": "Vrai ou faux : la grande aiguille indique les minutes.", "opts": ["Vrai", "Faux"], "ans": 0, "ok": "Oui : vrai.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "Vrai ou faux : quand la grande aiguille est sur le 6, il est toujours exactement 6 heures.", "opts": ["Vrai", "Faux"], "ans": 1, "ok": "Oui : faux, elle indique 30 minutes.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "Vrai ou faux : quand la grande aiguille est sur le 12, c'est une heure entière.", "opts": ["Vrai", "Faux"], "ans": 0, "ok": "Oui : vrai.", "ko": "Regarde bien et réessaie."}]}, {"id": "he-2", "name": "Les heures et les quarts d'heure", "sub": "Quart, demie, trois quarts", "cls": "gn", "badge": "🕘", "steps": [{"t": "teach", "title": "Un tour, une heure", "say": "Quand la grande aiguille fait un tour complet, 60 minutes se sont écoulées : c'est 1 heure. Fais faire un tour à la grande aiguille.", "html": "<p class=\"big\">Quand la grande aiguille fait <b>un tour complet</b>, 60 minutes ont passé : c'est <b>1 heure</b>.</p><div id=\"mrw\"></div>", "js": "w-clk", "chk": {"q": "Un tour complet de la grande aiguille, c'est…", "o": ["60 minutes", "12 minutes"], "a": 0}}, {"t": "teach", "title": "Les quatre repères", "say": "Grande aiguille sur le 12 : heure entière. Sur le 3 : 15 minutes, un quart d'heure. Sur le 6 : 30 minutes, une demi-heure. Sur le 9 : 45 minutes, trois quarts d'heure.", "html": "<div class=\"ckrow\"><div class=\"ckw\"><div data-clk=\"-:0\" data-sz=\"128\"></div><b>12 → pile</b></div><div class=\"ckw\"><div data-clk=\"-:15\" data-sz=\"128\"></div><b>3 → 15 min</b></div><div class=\"ckw\"><div data-clk=\"-:30\" data-sz=\"128\"></div><b>6 → 30 min</b></div><div class=\"ckw\"><div data-clk=\"-:45\" data-sz=\"128\"></div><b>9 → 45 min</b></div></div><p>15 min : un <b>quart d'heure</b><br>30 min : une <b>demi-heure</b><br>45 min : <b>trois quarts d'heure</b></p>", "js": "w-anim", "chk": {"q": "Une demi-heure, c'est…", "o": ["30 minutes", "15 minutes"], "a": 0}}, {"t": "teach", "title": "Je dis l'heure", "say": "8 heures 15 : huit heures et quart. 8 heures 30 : huit heures et demie. 8 heures 45 : neuf heures moins le quart, ou huit heures quarante-cinq.", "html": "<div class=\"ckrow\"><div class=\"ckw\"><div data-clk=\"8:15\" data-sz=\"128\"></div><b>8 h 15</b></div><div class=\"ckw\"><div data-clk=\"8:30\" data-sz=\"128\"></div><b>8 h 30</b></div><div class=\"ckw\"><div data-clk=\"8:45\" data-sz=\"128\"></div><b>8 h 45</b></div></div><p>8 h 15 : huit heures <b>et quart</b><br>8 h 30 : huit heures <b>et demie</b><br>8 h 45 : huit heures quarante-cinq, ou neuf heures <b>moins le quart</b></p>", "js": "w-anim", "chk": {"q": "8 h 30, c'est huit heures…", "o": ["et demie", "et quart"], "a": 0}}, {"t": "match", "q": "Associe.", "pairs": [{"l": "Un quart d'heure", "r": "15 min"}, {"l": "Une demi-heure", "r": "30 min"}, {"l": "Trois quarts d'heure", "r": "45 min"}, {"l": "Une heure entière", "r": "60 min"}]}, {"t": "teach", "js": "w-pick", "title": "Choisis la bonne horloge", "say": "Il est 3 h 15. Quelle horloge ?", "html": "<p class=\"big\">Il est 3 h 15. Quelle horloge ?</p><div class=\"ckrow\"><div class=\"ckw\"><div data-clk=\"3:45\" data-sz=\"128\"></div><b>A</b></div><div class=\"ckw\"><div data-clk=\"3:15\" data-sz=\"128\"></div><b>B</b></div><div class=\"ckw\"><div data-clk=\"12:15\" data-sz=\"128\"></div><b>C</b></div></div><div id=\"mrw\"></div>", "opts": ["A", "B", "C"], "ans": 1, "ok": "Oui : l'horloge B : grande aiguille sur le 3, petite juste après le 3.", "ko": "La grande aiguille doit pointer sur le 3."}, {"t": "choice", "q": "6 h 30, c'est 6 heures et ___ minutes.", "opts": ["15", "30", "45"], "ans": 1, "ok": "Oui : 30 minutes.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "10 h 15, c'est 10 heures et ___ minutes.", "opts": ["15", "30", "45"], "ans": 0, "ok": "Oui : 15 minutes.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "À 1 h 45, la grande aiguille est sur le ___.", "opts": ["3", "6", "9"], "ans": 2, "ok": "Oui : sur le 9.", "ko": "Regarde bien et réessaie."}, {"t": "build", "q": "Range les heures dans l'ordre de la journée.", "words": ["2 h 45", "2 h 15", "2 h 30", "2 h"], "ans": "2 h 2 h 15 2 h 30 2 h 45", "ok": "Bravo : 2 h, 2 h 15, 2 h 30, 2 h 45.", "ko": "Commence par la plus tôt."}, {"t": "teach", "js": "w-clk", "mode": "set", "title": "Le cadran en mouvement", "say": "Règle l'horloge : il est 11 h 15.", "html": "<p class=\"big\">🃏 Il est <b>11 h 15</b>. Règle l'horloge !</p><div id=\"mrw\"></div>", "h": 11, "m": 15}, {"t": "teach", "js": "w-clk", "mode": "set", "title": "Le cadran en mouvement", "say": "Règle l'horloge : il est 4 h 30.", "html": "<p class=\"big\">🃏 Il est <b>4 h 30</b>. Règle l'horloge !</p><div id=\"mrw\"></div>", "h": 4, "m": 30}, {"t": "teach", "js": "w-clk", "mode": "set", "title": "Le cadran en mouvement", "say": "Règle l'horloge : il est 7 h 45.", "html": "<p class=\"big\">🃏 Il est <b>7 h 45</b>. Règle l'horloge !</p><div id=\"mrw\"></div>", "h": 7, "m": 45}, {"t": "teach", "js": "w-clk", "mode": "set", "title": "Le cadran en mouvement", "say": "Règle l'horloge : il est 12 h.", "html": "<p class=\"big\">🃏 Il est <b>12 h</b>. Règle l'horloge !</p><div id=\"mrw\"></div>", "h": 12, "m": 0}]}, {"id": "he-3", "name": "Combien de temps s'est écoulé ?", "sub": "Les durées", "cls": "gn", "badge": "⏳", "steps": [{"t": "teach", "title": "La durée", "say": "Une durée, c'est le temps qui passe entre le début et la fin d'une activité. Pour trouver une durée, je peux avancer sur une ligne du temps. Le film commence à 2 heures et se termine à 3 heures : il s'écoule 1 heure. Le jeu commence à 4 heures et se termine à 4 heures 30 : il s'écoule 30 minutes.", "html": "<p class=\"big\">Une <b>durée</b>, c'est le temps qui passe entre le <b>début</b> et la <b>fin</b>.</p><p>🎬 Le film : de 2 h à 3 h → <b>1 heure</b><br>🎲 Le jeu : de 4 h à 4 h 30 → <b>30 minutes</b></p><p>Pour trouver une durée, j'avance sur la ligne du temps avec la grenouille 🐸.</p>", "chk": {"q": "Une durée, c'est…", "o": ["le temps qui passe", "l'heure du début"], "a": 0}}, {"t": "teach", "js": "w-line", "title": "Compte les bonds", "say": "De 9 h à 10 h : fais sauter la grenouille.", "html": "<p class=\"big\">De 9 h à 10 h : fais sauter la grenouille.</p><div id=\"mrw\"></div>", "labels": ["9 h", "10 h"], "from": 0, "to": 1, "per": 60, "q": "Combien de temps ?", "opts": ["1 heure", "10 minutes", "9 heures"], "ans": 0, "ok": "Oui : 1 heure.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "js": "w-line", "title": "Compte les bonds", "say": "De 1 h à 1 h 30.", "html": "<p class=\"big\">De 1 h à 1 h 30.</p><div id=\"mrw\"></div>", "labels": ["1 h", "1 h 15", "1 h 30", "1 h 45"], "from": 0, "to": 2, "per": 15, "q": "Combien de temps ?", "opts": ["15 minutes", "30 minutes", "1 heure"], "ans": 1, "ok": "Oui : 30 minutes.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "js": "w-line", "title": "Compte les bonds", "say": "De 3 h à 3 h 15.", "html": "<p class=\"big\">De 3 h à 3 h 15.</p><div id=\"mrw\"></div>", "labels": ["3 h", "3 h 15", "3 h 30"], "from": 0, "to": 1, "per": 15, "q": "Combien de temps ?", "opts": ["15 minutes", "30 minutes", "3 minutes"], "ans": 0, "ok": "Oui : 15 minutes.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "js": "w-line", "title": "Compte les bonds", "say": "De 6 h 15 à 6 h 45.", "html": "<p class=\"big\">De 6 h 15 à 6 h 45.</p><div id=\"mrw\"></div>", "labels": ["6 h", "6 h 15", "6 h 30", "6 h 45"], "from": 1, "to": 3, "per": 15, "q": "Combien de temps ?", "opts": ["15 minutes", "30 minutes", "45 minutes"], "ans": 1, "ok": "Oui : 30 minutes.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "js": "w-line", "title": "Trouve l'heure de fin", "say": "La lecture commence à 5 h. Elle dure 1 heure.", "html": "<p class=\"big\">La lecture commence à 5 h. Elle dure 1 heure.</p><div id=\"mrw\"></div>", "labels": ["5 h", "6 h", "7 h"], "from": 0, "to": 1, "per": 60, "q": "À quelle heure finit-elle ?", "opts": ["5 h 30", "6 h", "7 h"], "ans": 1, "ok": "Oui : elle finit à 6 h.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "js": "w-line", "title": "Trouve l'heure de fin", "say": "Le goûter commence à 4 h. Il dure 30 minutes.", "html": "<p class=\"big\">Le goûter commence à 4 h. Il dure 30 minutes.</p><div id=\"mrw\"></div>", "labels": ["4 h", "4 h 15", "4 h 30", "4 h 45"], "from": 0, "to": 2, "per": 15, "q": "À quelle heure finit-il ?", "opts": ["4 h 15", "4 h 30", "5 h"], "ans": 1, "ok": "Oui : il finit à 4 h 30.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "js": "w-line", "title": "Trouve l'heure de fin", "say": "L'entraînement commence à 10 h 15. Il dure 15 minutes.", "html": "<p class=\"big\">L'entraînement commence à 10 h 15. Il dure 15 minutes.</p><div id=\"mrw\"></div>", "labels": ["10 h", "10 h 15", "10 h 30", "10 h 45"], "from": 1, "to": 2, "per": 15, "q": "À quelle heure finit-il ?", "opts": ["10 h 30", "10 h 45", "11 h"], "ans": 0, "ok": "Oui : il finit à 10 h 30.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "js": "w-line", "title": "Trouve l'heure du début", "say": "Le dessin animé finit à 7 h. Il dure 30 minutes. Recule !", "html": "<p class=\"big\">Le dessin animé finit à 7 h. Il dure 30 minutes. Recule !</p><div id=\"mrw\"></div>", "labels": ["6 h 15", "6 h 30", "6 h 45", "7 h"], "from": 3, "to": 1, "per": 15, "q": "À quelle heure a-t-il commencé ?", "opts": ["6 h 30", "7 h 30", "6 h"], "ans": 0, "ok": "Oui : il a commencé à 6 h 30.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "js": "w-line", "title": "Le problème de Rico", "say": "Rico part en promenade à 9 h 15. Il rentre à 9 h 45.", "html": "<p class=\"big\">Rico part en promenade à 9 h 15. Il rentre à 9 h 45.</p><div id=\"mrw\"></div>", "labels": ["9 h", "9 h 15", "9 h 30", "9 h 45"], "from": 1, "to": 3, "per": 15, "q": "Combien de temps a duré sa promenade ?", "opts": ["15 minutes", "30 minutes", "45 minutes"], "ans": 1, "ok": "Oui : 30 minutes.", "ko": "Compte les bonds de la grenouille."}, {"t": "teach", "title": "Attention à la question", "say": "Une course débute à 2 heures 30 et s'arrête à 3 heures. Ne confonds pas l'heure de départ, l'heure de fin et la durée.", "html": "<p class=\"big\">🏃 Une course débute à <b>2 h 30</b> et s'arrête à <b>3 h</b>.</p><p>Ne confonds pas : l'heure de <b>départ</b>, l'heure de <b>fin</b> et la <b>durée</b>.</p>", "chk": {"q": "La durée, c'est…", "o": ["le temps entre le début et la fin", "l'heure affichée"], "a": 0}}, {"t": "choice", "q": "Quelle est l'heure de départ ?", "opts": ["2 h 30", "3 h", "30 minutes"], "ans": 0, "ok": "Oui : 2 h 30.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "Quelle est l'heure de fin ?", "opts": ["2 h 30", "3 h", "30 minutes"], "ans": 1, "ok": "Oui : 3 h.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "Quelle est la durée ?", "opts": ["2 h 30", "3 h", "30 minutes"], "ans": 2, "ok": "Oui : 30 minutes.", "ko": "Regarde bien et réessaie."}]}, {"id": "he-4", "name": "Je lis le calendrier", "sub": "Jours, mois, dates", "cls": "gn", "badge": "📅", "steps": [{"t": "teach", "title": "La semaine et l'année", "say": "Un calendrier aide à se repérer dans le temps. Une semaine compte 7 jours : lundi, mardi, mercredi, jeudi, vendredi, samedi, dimanche. Une année compte 12 mois. Les mois se suivent toujours dans le même ordre, de janvier à décembre.", "html": "<p class=\"big\">Une <b>semaine</b> compte <b>7 jours</b>.</p><p>lundi · mardi · mercredi · jeudi · vendredi · samedi · dimanche</p><p class=\"big\">Une <b>année</b> compte <b>12 mois</b>.</p><p>janvier · février · mars · avril · mai · juin · juillet · août · septembre · octobre · novembre · décembre</p>", "chk": {"q": "Une semaine compte…", "o": ["7 jours", "12 jours"], "a": 0}}, {"t": "teach", "title": "Trouver une date", "say": "Pour trouver une date, je repère d'abord le mois, puis la colonne du jour et le nombre. Une fête est inscrite le samedi 21 novembre : le mois est novembre, le jour de la semaine est samedi, la date est le 21. Touche les jours du calendrier pour voir leur nom.", "html": "<p class=\"big\">Je repère le <b>mois</b>, puis la <b>colonne du jour</b> et le <b>nombre</b>.</p><div id=\"mrw\"></div><p>🎉 Fête le samedi 21 novembre : mois → novembre, jour → samedi, date → le 21.</p>", "js": "w-cal", "chk": {"q": "Je repère d'abord…", "o": ["le mois", "le nombre"], "a": 0}}, {"t": "teach", "js": "w-cal", "title": "Trouve la date", "say": "Touche le samedi 21 novembre.", "html": "<p class=\"big\">Touche le <b>samedi 21 novembre</b>.</p><div id=\"mrw\"></div>", "target": 21}, {"t": "teach", "js": "w-cal", "title": "Trouve la date", "say": "Touche le mercredi 11 novembre.", "html": "<p class=\"big\">Touche le <b>mercredi 11 novembre</b>.</p><div id=\"mrw\"></div>", "target": 11}, {"t": "build", "q": "Remets les jours dans l'ordre.", "words": ["jeudi", "lundi", "dimanche", "mardi", "samedi", "mercredi", "vendredi"], "ans": "lundi mardi mercredi jeudi vendredi samedi dimanche", "ok": "Bravo, c'est la semaine !", "ko": "La semaine commence par lundi."}, {"t": "choice", "q": "Le jour après mardi :", "opts": ["lundi", "mercredi", "jeudi"], "ans": 1, "ok": "Oui : mercredi.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "Le jour avant dimanche :", "opts": ["samedi", "lundi", "vendredi"], "ans": 0, "ok": "Oui : samedi.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "Le jour après vendredi :", "opts": ["jeudi", "dimanche", "samedi"], "ans": 2, "ok": "Oui : samedi.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "janvier, février, ___, avril", "opts": ["mai", "mars", "juin"], "ans": 1, "ok": "Oui : mars.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "juin, juillet, ___, septembre", "opts": ["août", "octobre", "mai"], "ans": 0, "ok": "Oui : août.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "octobre, novembre, ___", "opts": ["janvier", "septembre", "décembre"], "ans": 2, "ok": "Oui : décembre.", "ko": "Regarde bien et réessaie."}, {"t": "teach", "title": "Les événements", "say": "Sortie : mercredi 12 mars. Anniversaire : samedi 21 novembre. Visite : lundi 5 mai.", "html": "<p class=\"big\">🚌 Sortie : mercredi 12 mars<br>🎂 Anniversaire : samedi 21 novembre<br>🏰 Visite : lundi 5 mai</p>"}, {"t": "choice", "q": "🚌 Sortie : mercredi 12 mars · 🎂 Anniversaire : samedi 21 novembre · 🏰 Visite : lundi 5 mai. Quel événement a lieu en novembre ?", "opts": ["La sortie", "L'anniversaire", "La visite"], "ans": 1, "ok": "Oui : l'anniversaire.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "🚌 Sortie : mercredi 12 mars · 🎂 Anniversaire : samedi 21 novembre · 🏰 Visite : lundi 5 mai. Quel événement a lieu un mercredi ?", "opts": ["La sortie", "L'anniversaire", "La visite"], "ans": 0, "ok": "Oui : la sortie.", "ko": "Regarde bien et réessaie."}, {"t": "choice", "q": "🚌 Sortie : mercredi 12 mars · 🎂 Anniversaire : samedi 21 novembre · 🏰 Visite : lundi 5 mai. Quelle est la date de la visite ?", "opts": ["Lundi 5 mai", "Mercredi 12 mars", "Lundi 12 mai"], "ans": 0, "ok": "Oui : lundi 5 mai.", "ko": "Regarde bien et réessaie."}, {"t": "teach", "js": "w-line", "title": "Combien de jours attendre ?", "say": "Nous sommes lundi. Une sortie est prévue jeudi. Avance jour par jour.", "html": "<p class=\"big\">Nous sommes lundi. Une sortie est prévue jeudi. Avance jour par jour.</p><div id=\"mrw\"></div>", "labels": ["lun.", "mar.", "mer.", "jeu.", "ven.", "sam.", "dim."], "from": 0, "to": 3, "per": 0, "q": "Dans combien de jours ?", "opts": ["2 jours", "3 jours", "4 jours"], "ans": 1, "ok": "Oui : dans 3 jours : mardi, mercredi, jeudi.", "ko": "Compte les bonds de la grenouille."}]}, {"id": "he-fin", "name": "Mission finale : la journée de Rico", "sub": "Le défi de l'heure", "cls": "gn", "badge": "🏆", "steps": [{"t": "teach", "title": "La journée de Rico", "say": "Voici le programme de Rico. Petit-déjeuner : 8 heures. Départ pour l'école : 8 heures 30. Récréation : 10 heures 15. Fin de la classe : 12 heures. Entraînement : 16 heures 30.", "bilreset": 1, "html": "<table class=\"mrprog\"><tr><td>🥣 Petit-déjeuner</td><td>8 h</td></tr><tr><td>🎒 Départ pour l'école</td><td>8 h 30</td></tr><tr><td>⚽ Récréation</td><td>10 h 15</td></tr><tr><td>🔔 Fin de la classe</td><td>12 h</td></tr><tr><td>🏃 Entraînement</td><td>16 h 30</td></tr></table>"}, {"t": "choice", "q": "🎒 Départ pour l'école : 8 h 30. À quelle heure Rico part-il pour l'école ?", "opts": ["8 h", "8 h 30", "10 h 15"], "ans": 1, "ok": "Oui : 8 h 30.", "ko": "Regarde bien et réessaie.", "nt": "Lire l'heure"}, {"t": "teach", "js": "w-pick", "title": "La récréation", "say": "Il est 10 h 15. Quelle aiguille pointe sur le 3 ?", "html": "<p class=\"big\">Il est 10 h 15. Quelle aiguille pointe sur le 3 ?</p><div class=\"ckw\"><div data-clk=\"10:15\" data-sz=\"190\"></div></div><div id=\"mrw\"></div>", "opts": ["La grande aiguille, celle des minutes", "La petite aiguille, celle des heures"], "ans": 0, "ok": "Oui : la grande aiguille des minutes.", "ko": "Regarde bien les aiguilles.", "nt": "Lire l'heure"}, {"t": "teach", "js": "w-clk", "mode": "set", "title": "Le départ pour l'école", "say": "Règle l'horloge : il est 8 h 30.", "html": "<p class=\"big\">🃏 Il est <b>8 h 30</b>. Règle l'horloge !</p><div id=\"mrw\"></div>", "h": 8, "m": 30, "nt": "Placer les aiguilles"}, {"t": "teach", "js": "w-line", "title": "Le petit-déjeuner", "say": "De 8 h à 8 h 30.", "html": "<p class=\"big\">De 8 h à 8 h 30.</p><div id=\"mrw\"></div>", "labels": ["8 h", "8 h 15", "8 h 30", "8 h 45"], "from": 0, "to": 2, "per": 15, "q": "Combien de temps s'écoule ?", "opts": ["15 minutes", "30 minutes", "1 heure"], "ans": 1, "ok": "Oui : 30 minutes.", "ko": "Compte les bonds de la grenouille.", "nt": "Trouver une durée"}, {"t": "teach", "js": "w-line", "title": "L'entraînement", "say": "L'entraînement commence à 16 h 30. Il dure 30 minutes.", "html": "<p class=\"big\">L'entraînement commence à 16 h 30. Il dure 30 minutes.</p><div id=\"mrw\"></div>", "labels": ["16 h 30", "16 h 45", "17 h", "17 h 15"], "from": 0, "to": 2, "per": 15, "q": "À quelle heure se termine-t-il ?", "opts": ["16 h 45", "17 h", "17 h 30"], "ans": 1, "ok": "Oui : il se termine à 17 h.", "ko": "Compte les bonds de la grenouille.", "nt": "Début, fin, durée"}, {"t": "choice", "q": "Quel jour vient après mercredi ?", "opts": ["mardi", "jeudi", "vendredi"], "ans": 1, "ok": "Oui : jeudi.", "ko": "Regarde bien et réessaie.", "nt": "Jours et mois"}, {"t": "teach", "js": "w-cal", "title": "Le calendrier", "say": "Touche le samedi 21 novembre.", "html": "<p class=\"big\">Touche le <b>samedi 21 novembre</b>.</p><div id=\"mrw\"></div>", "target": 21, "nt": "Calendrier"}, {"t": "build", "q": "Dans quel ordre se passent ces événements ?", "words": ["récréation", "petit-déjeuner", "entraînement"], "ans": "petit-déjeuner récréation entraînement", "ok": "Bravo : petit-déjeuner, récréation, entraînement.", "ko": "Que fait Rico en premier le matin ?", "nt": "Lire l'heure"}, {"t": "teach", "js": "bilend", "title": "Bilan", "say": "", "html": ""}]}]);
