  var EX={choice:1,build:1,sort:1,match:1,tapmany:1,num:1,tap:1,col:1,bpick:1,ck:1,fr:1,metier:1};
  if(s.t==='teach'?!(/^w-/.test(s.js||'')&&s.js!=='w-share'):!EX[s.t])return;
